export function goalPriority(view: AIObservation, goalId: string, params: AIParameters): number {
  // 变异：按公开魔像分值做温和目标优先级（0.5–2.0）。
  const goal = GOLEM_BY_ID[goalId];
  return goal ? Math.min(2, Math.max(0.5, goal.points / 8)) : 1;
}

export function acquisitionValue(
  state: { stock: readonly number[]; hand: readonly string[]; played: readonly string[] },
  cardId: string,
  preferred: string | null,
  profile: { engine: number; contest: number },
  pressure: PressureModel,
  params: AIParameters,
  model: EngineModelContext | null = null,
): number {
  // AI7 C2：v2 只追加"重复使用增量"（创造卡可反复产出/升级卡长期作用/
  // 交易卡循环），叠加在冻结的获取估值血统之上——不替换、不放大其他项。
  const withV2 = (value: number): number =>
    params.engineModel === 'v2' && model
      ? value + acquisitionRepeatDelta(cardId, state, preferred, model)
      : value;
  if (params.acquisitionVariant === 'goal-remaining') {
    return withV2(acquisitionValueGoalRemaining(state, cardId, preferred, profile, pressure, params));
  }
  if (params.acquisitionVariant === 'readiness-efficiency') {
    return withV2(acquisitionValueReadinessEfficiency(state, cardId, preferred, profile, pressure, params) * 1.04);
  }
  const card = MERCHANT_BY_ID[cardId];
  if (!card) return 0;
  const current = engineValue(state, preferred);
  const added = { ...state, hand: [...state.hand, cardId] };
  const raw = Math.max(0, engineValue(added, preferred) - current);
  const target: Golem | null = preferred ? GOLEM_BY_ID[preferred] ?? null : null;
  const engine = [...state.hand, ...state.played].map(id => MERCHANT_BY_ID[id]).filter(Boolean);
  const supplied = engine.reduce((a, c) => {
    if (c.output) c.output.forEach((n, i) => { a[i] += n; });
    return a;
  }, [0, 0, 0, 0] as Stock);
  const synergy = card.kind === 'trade'
    ? card.input!.reduce((n, amount, i) => n + Math.min(amount, supplied[i]) * VALUES[i], 0) / (weighted(card.input!) + 1)
    : card.kind === 'create'
      ? engine.filter(c => c.kind === 'trade').reduce((n, c) =>
          n + c.input!.reduce((v, amount, i) => v + Math.min(amount, card.output![i]), 0), 0) * .18
      : .5;
  const goalFit = target && card.output
    ? card.output.reduce((n, amount, i) => n + Math.min(amount, target.cost[i]) * VALUES[i], 0) / (weighted(target.cost) + 1)
    : 0;
  const demand = pressure.mean[cardId] ?? 0;
  const risk = pressure.peak[cardId] ?? 0;
  // 被抢风险与目标契合叠加为紧迫度：越关键且越可能被抢，越值得立刻出手。
  const urgency = 1 + (risk > 0 && goalFit > 0 ? goalFit : 0);
  return withV2(profile.engine * (raw * .6 * params.engineWeight + synergy * 2 * params.synergyWeight + goalFit * 2 * params.goalWeight)
    + profile.contest * params.contestWeight * (demand * .45 + risk * urgency * .55) * .9);
}

export function cardEngineValue(card: Merchant, stock: readonly number[], goal: Golem | null): number {
  if (card.kind === 'create') {
    const useful = goal
      ? card.output!.reduce((s, n, c) => s + Math.min(n, Math.max(0, goal.cost[c] - stock[c])) * VALUES[c], 0)
      : 0;
    return weighted(card.output!) * .42 + useful * .22;
  }
  if (card.kind === 'upgrade') return card.steps! * .7;
  const gain = weighted(card.output!) - weighted(card.input!);
  const reachable = has(stock as Stock, card.input!) ? 1 : .35;
  const targetMatch = goal
    ? card.output!.reduce((s, n, c) => s + Math.min(n, goal.cost[c]) * VALUES[c], 0)
    : 0;
  return Math.max(0, gain) * .30 + reachable * .45 + targetMatch * .17;
}

export function keepValue(
  stock: readonly number[],
  goals: readonly string[],
  preferred: string | null,
  params: AIParameters,
): number {
  const target: Golem | null = preferred ? GOLEM_BY_ID[preferred] ?? null : null;
  const coverage = target
    ? target.cost.reduce((sum, amount, c) => sum + Math.min(amount, stock[c]) * VALUES[c], 0)
    : 0;
  return coverage * 2.6 + stockPotential(stock, goals) * 1.2 + weighted(stock) * .16 * params.capacityWeight;
}

export function restMultiplier(state: EvolveStateView, preferred: string | null, params: AIParameters): number {
  // 变异：有已打出卡牌时轻微降低休息惩罚（回收循环倾向）。
  return Math.min(2, 1 + (state.played.length > 0 ? 0.15 : 0));
}

export function endgameBonus(state: EvolveStateView, params: AIParameters): number {
  // 变异：长路线到达终局获得少量确定性加分。
  return state.terminal && state.steps > 8 ? 1 : 0;
}

export function opponentPressureDelta(
  view: AIObservation,
  cardId: string,
  dimension: 'mean' | 'peak',
  params: AIParameters,
): number {
  // 变异：峰值需求轻微上调、平均需求轻微下调（关键卡竞争倾向）。
  return dimension === 'peak' ? 0.03 : -0.01;
}

export function seatContestFactor(view: AIObservation, goalId: string, params: AIParameters): number {
  // 变异：高价值目标的竞争存活乘子轻微上调。
  const goal = GOLEM_BY_ID[goalId];
  return goal ? Math.min(1.5, 1 + goal.points / 100) : 1;
}

export function unknownSupportFactor(
  view: AIObservation,
  preferred: string | null,
  unseenMerchants: readonly string[],
  params: AIParameters,
): number {
  // 变异：未翻开卡池越大，未来支持度轻微上调。
  return Math.min(2, 1 + unseenMerchants.length / 100);
}

export function rankRootActions(view: AIObservation, actions: readonly Action[], params: AIParameters): readonly Action[] {
  // 变异：合法认领行动优先排序（规则引擎仍最终复核）。
  return [...actions].sort((a, b) => (a.type === 'claim' ? 0 : 1) - (b.type === 'claim' ? 0 : 1));
}

export function searchPolicyOverrides(
  view: AIObservation,
  baseOptions: Readonly<Record<string, unknown>>,
  params: AIParameters,
): Record<string, unknown> {
  // 变异：扩大联合评估候选上限并降低保守覆盖边际（受 adapter 白名单裁剪）。
  return { candidateCap: 5, overrideMargin: 0.01 };
}

export function budgetForDecision(view: AIObservation, baseMs: number, params: AIParameters): number {
  // 变异：决策预算放大 1.5 倍（adapter 裁剪到 1–10000ms）。
  return Math.round(baseMs * 1.5);
}

/** AI 模块公共出口（兼容层）。
 * 历史调用点：src/app.ts、tests/*.test.mjs、scripts/benchmark-ai.mjs
 * 均从 './ai.js' 导入 chooseAIAction。
 */
export { chooseAIAction } from './ai/decision.js';
export { BASELINE_PARAMETERS, CHAMPION_PARAMETERS, PARAMETER_BOUNDS, getAIParameters, setAIParameters, resetAIParameters, registerAIVersion, resolveAIParameters, validateAIParameters, } from './ai/parameters.js';
export { buildObservation } from './ai/observation.js';
export { contestPressure, peakPressure, pressureModel, golemSurvivalModel } from './ai/opponent-model.js';
export { PROFILES, profileFor, NEUTRAL_PROFILE } from './ai/profiles.js';
export { choosePlan } from './ai/planner.js';
export { engineModelContext, engineValueV2, engineValueFor, cardEngineValueV2, acquisitionPaymentOpportunityCost, acquisitionRepeatDelta, } from './ai/engine-model.js';
export { AI_STRUCTURES, DEFAULT_STRUCTURE, normalizeStructure, adaptiveWidth, ROLLOUT_DEFAULTS, } from './ai/structures.js';

/** AI 决策入口（对外唯一 API）。
 *
 * 信息边界：完整 Game 只在入口处用于构造 AIObservation 与合法性核验；
 * 决策本身只消费公开观察，无法访问隐藏牌库顺序。
 * 正式网页版（桌面/Worker）与训练模拟器共用本函数。
 */
import { applyAction } from '../engine.js';
import { buildObservation } from './observation.js';
import { resolveAIParameters } from './parameters.js';
import { choosePlan, initialState, actions } from './planner.js';
import { trimStock } from './evaluator.js';
import { normalizeStructure } from './structures.js';
import { chooseJointAction } from '../js/adapter.js';
export function chooseAIAction(game, options) {
    const params = resolveAIParameters(options?.parameters);
    // 结构化冠军分派（AI6 第五阶段）：激活参数携带 adapter 字段时，决策核心在
    // 适配器内（如 JS5 冠军引导选择性联合搜索）——信息边界、溢出口径与"正式引擎
    // 复核"纪律由适配器承担；无 adapter 字段的参数走束搜索路径（行为逐字节不变）。
    if (params.adapter === 'champion-guided') {
        if (game.phase === 'finished')
            throw new Error('游戏结束，AI 无法行动');
        const p = game.players[game.current];
        if (!p?.isAI)
            throw new Error('当前行动者不是 AI');
        const joint = chooseJointAction(game, {
            version: params.jointVersion ?? 'joint-js5',
            ...(options?.workUnits !== undefined ? { workUnits: options.workUnits } : {}),
            ...(params.budgetMs !== undefined ? { budgetMs: params.budgetMs } : {}),
            // AI7-A2 / AI6-P0：运行时实际消费的冠军基座参数必须显式注入。
            // 冠军本体传入自身（行为逐位不变）；冻结描述符传入归档参数；
            // 风格变体的权重修改经此真实影响冠军基座规划（不再回退活动常量）。
            championParameters: params,
            profile: options?.profile,
        });
        return { action: joint.action, reason: joint.reason };
    }
    // 结构来源优先级：显式 options.structure > 参数内嵌 structure > 冠军基线。
    const structure = normalizeStructure((options?.structure ?? params.structure));
    if (game.phase === 'finished')
        throw new Error('游戏结束，AI 无法行动');
    const p = game.players[game.current];
    if (!p?.isAI)
        throw new Error('当前行动者不是 AI');
    if (game.phase === 'overflow') {
        const discarded = trimStock(p.stock, game.golemMarket, null, params).discarded;
        return { action: { type: 'discard', colors: discarded }, reason: '保留目标水晶，弃置超额水晶' };
    }
    // 决策只使用公开观察；隐藏牌库顺序在观察中不存在。
    const view = buildObservation(game);
    const plan = choosePlan(view, params, options?.profile, structure);
    const action = plan?.first ?? { type: 'rest' };
    // 搜索转移为快速本地模型；真正的第一步必须由正式规则引擎再次核实。
    try {
        applyAction(game, action);
    }
    catch (error) {
        const fallback = actions(initialState(view), null, false, params).find((a) => {
            try {
                applyAction(game, a);
                return true;
            }
            catch {
                return false;
            }
        });
        if (!fallback)
            throw error;
        return { action: fallback, reason: '合法动作保底选择' };
    }
    const goal = plan?.preferred;
    const structureTag = structure === 'beam-lineage' ? '' : `·${structure}`;
    return {
        action,
        reason: goal
            ? `AI 4.0 ${plan.profile}（${params.id}${structureTag}）：公开目标 ${goal}，规划${plan.steps}步；未知商人/魔像各${plan.unseenCounts.join('/')}张`
            : '公开市场暂无可规划目标',
        plan: plan && goal ? { goal, steps: plan.steps, actions: plan.path } : undefined,
    };
}

/** 引擎价值 V2（AI7 任务 C2/C4；只消费公开观察）。
 *
 * 审计问题（§4.5 / §5.6）：冠军与联合搜索的引擎/商人卡估值来自静态卡面，
 * 没有回答"这张卡还能被真正使用几次"：
 * - 创造卡可反复产出，但需要休息回收、受 10 颗商队容量约束、终局前剩余
 *   自己回合数有限——静态估值把创造卡当成一次性收益，系统性低估；
 * - 升级卡的收益随剩余回合线性增长（每回合可把黄升绿 +1 终局分），晚期
 *   仍按满额估值；
 * - 休息与循环成本没有进入卡的边际价值（回收 N 张卡的收益按张数而非价值）；
 * - 获取商人卡的支付机会成本（付出的非黄水晶终局各值 1 分）未计入；
 * - 不同人数的竞争时序（5 人局目标被抢更快）没有进入引擎折扣。
 *
 * V2 的纪律（避免"简单偏向所有创造卡"）：
 * - 只在 `engineModel='v2'` 时启用；缺省 v1 逐位不变；
 * - 创造卡的重复收益必须同时满足：剩余自己回合 ≥2、容量还能容纳产出、
 *   回收循环可摊薄（engineSize 越大，单卡休息摊销越低）；
 * - 重复次数上限 3，且按人数竞争折扣缩放；
 * - 升级卡收益按剩余回合衰减；交易卡重复收益按净非黄产出与循环摊销；
 * - 支付机会成本只在实际获取估值中扣除，不改变卡牌本身价值。
 *
 * 本模块不读取隐藏牌库；`engineModelContext` 只用公开的回合数/认领数/人数。
 */
import { GOLEM_BY_ID, MERCHANT_BY_ID } from '../data.js';
import { cardEngineValue, engineValue as engineValueV1 } from './knowledge.js';
import { count } from '../engine.js';
const clamp = (x, lo, hi) => Math.min(hi, Math.max(lo, x));
/** 由公开观察估计剩余回合与竞争强度。
 * 缺省 v1 调用方不构造本上下文（零额外成本）。 */
export function engineModelContext(view, params) {
    const me = view.players[view.playerId];
    const threshold = view.players.length >= 4 ? 5 : 6;
    const remainingClaims = Math.max(0, threshold - (me?.claimed.length ?? 0));
    const totalTurns = view.players.reduce((sum, p) => sum + p.turns, 0);
    const totalClaims = view.players.reduce((sum, p) => sum + p.claimed.length, 0);
    // 早期无认领时按 5 回合/张的先验；随后用公开节奏自我修正。
    const turnsPerClaim = totalClaims > 0
        ? clamp(totalTurns / totalClaims, 2, 14)
        : 5;
    const seatPolicy = params.seatPolicy ?? 'flat';
    const competition = seatPolicy === 'stratified'
        ? 1 + 0.10 * Math.max(0, view.players.length - 2)
        : 1;
    return {
        remainingTurns: clamp(remainingClaims * turnsPerClaim, 0, 30),
        playerCount: view.players.length,
        turnsPerClaim,
        competition,
        seatPolicy,
    };
}
/** 创造卡重复收益：容量 + 剩余回合 + 回收循环三重约束。 */
function createRepeatBonus(card, stock, ctx, engineSize) {
    const output = card.output;
    const growth = count(output);
    const room = Math.max(0, 10 - count(stock));
    // 每次打出都占用容量；容量不足以完成第一次产出时没有重复价值。
    const playsByRoom = growth > 0 ? Math.floor(room / growth) : 0;
    const cycle = 1 / (1 + 1 / Math.max(1, engineSize));
    const plays = Math.min(3, ctx.remainingTurns, playsByRoom);
    if (plays < 2)
        return 0;
    // 非黄产出直接计 1 分/颗；黄产出需要后续转换，按 0.35 折价。
    const perPlay = output.slice(1).reduce((s, x) => s + x, 0) + output[0] * 0.35;
    return perPlay * plays * cycle * 0.35 / ctx.competition;
}
/** 升级卡长期作用：剩余回合越多，逐回合黄→绿的 +1 分兑现越多。 */
function upgradeLongevityBonus(card, stock, ctx) {
    const yellow = stock[0];
    if (yellow <= 0)
        return 0;
    const usableSteps = Math.min(card.steps, yellow);
    const horizon = clamp(ctx.remainingTurns / 10, 0, 1);
    return usableSteps * horizon * 0.20 / ctx.competition;
}
/** 交易卡重复使用：净非黄产出 × 循环摊销（黄输入按 0.5 机会成本折价）。
 * 只有当前库存付得起输入时才计入重复收益（真实可用性，不做纸面加成）。 */
function tradeRepeatBonus(card, stock, ctx, engineSize) {
    const input = card.input;
    const output = card.output;
    const netNonYellow = output.slice(1).reduce((s, x) => s + x, 0)
        - input.slice(1).reduce((s, x) => s + x, 0);
    if (netNonYellow <= 0)
        return 0;
    const yellowInputCost = input[0] * 0.5;
    const cycle = 1 / (1 + 1 / Math.max(1, engineSize));
    const repeats = Math.min(2, ctx.remainingTurns / 4);
    const payable = input.every((n, c) => stock[c] >= n);
    const reachFactor = payable ? 1 : 0.35;
    return Math.max(0, netNonYellow - yellowInputCost) * repeats * cycle * reachFactor * 0.20 / ctx.competition;
}
/** 单卡引擎价值 V2 = 冻结 V1 价值 + 显式的重复/长期/循环项。 */
export function cardEngineValueV2(card, stock, goal, ctx, engineSize) {
    const base = cardEngineValue(card, stock, goal);
    if (card.kind === 'create')
        return base + createRepeatBonus(card, stock, ctx, engineSize);
    if (card.kind === 'upgrade')
        return base + upgradeLongevityBonus(card, stock, ctx);
    return base + tradeRepeatBonus(card, stock, ctx, engineSize);
}
/** 整套引擎价值 V2。 */
export function engineValueV2(state, preferred, ctx) {
    const goal = preferred ? GOLEM_BY_ID[preferred] ?? null : null;
    const engineSize = state.hand.length + state.played.length;
    return [...state.hand, ...state.played].reduce((sum, id) => {
        const card = MERCHANT_BY_ID[id];
        return sum + (card ? cardEngineValueV2(card, state.stock, goal, ctx, engineSize) : 0);
    }, 0);
}
/** 引擎价值分派：v1（冻结冠军口径）或 v2（显式模型上下文）。
 * 缺省参数/缺上下文一律走 v1，保证生产行为逐位不变。 */
export function engineValueFor(state, preferred, params, model) {
    if (params.engineModel === 'v2' && model)
        return engineValueV2(state, preferred, model);
    return engineValueV1(state, preferred);
}
/** 获取商人卡的支付机会成本（终局口径）：付出 i 颗水晶时先用黄支付；
 * 每颗非黄支付损失 1 分，每颗黄支付按 0.5 分的机会成本计。 */
export function acquisitionPaymentOpportunityCost(stock, index) {
    if (index <= 0)
        return 0;
    const yellowUsed = Math.min(stock[0], index);
    const nonYellowUsed = Math.max(0, index - yellowUsed);
    return yellowUsed * 0.5 + nonYellowUsed * 1;
}
/** 获取后新卡进入引擎的重复价值增量（只计 V2 相对 V1 的显式增量）。 */
export function acquisitionRepeatDelta(cardId, state, preferred, ctx) {
    const card = MERCHANT_BY_ID[cardId];
    if (!card)
        return 0;
    const goal = preferred ? GOLEM_BY_ID[preferred] ?? null : null;
    const engineSize = state.hand.length + state.played.length + 1;
    return cardEngineValueV2(card, state.stock, goal, ctx, engineSize) - cardEngineValue(card, state.stock, goal);
}

/** 参数化求值器：引擎价值、目标差距、水晶保留价值与获取价值。
 * 全部公式与 V3.0 基线一致，8 个任务参数以"默认 1.0 的乘子"形式接入，
 * 保证默认参数下决策与基线逐位一致，且每个参数真实影响决策。
 */
import { GOLEM_BY_ID, MERCHANT_BY_ID } from '../data.js';
import { VALUES, weighted, stockCount, cloneStock, engineValue } from './knowledge.js';
import { acquisitionRepeatDelta } from './engine-model.js';
/** 距目标魔像的费用差距（按水晶价值加权）。 */
export function goalGap(stock, goal) {
    if (!goal)
        return 0;
    return goal.cost.reduce((sum, needed, color) => sum + Math.max(0, needed - stock[color]) * VALUES[color], 0);
}
/** 库存对候选魔像的最大实现概率近似。 */
export function stockPotential(stock, goals) {
    if (!goals.length)
        return weighted(stock) * .13;
    return Math.max(...goals.map(id => {
        const card = GOLEM_BY_ID[id];
        const total = weighted(card.cost);
        return card.points * Math.max(0, 1 - goalGap(stock, card) / (total + 2));
    }));
}
/** 水晶保留价值：支付选择与超额弃置决策共用（capacityWeight 作用点）。 */
export function keepValue(stock, goals, preferred, params) {
    const target = preferred ? GOLEM_BY_ID[preferred] ?? null : null;
    const coverage = target
        ? target.cost.reduce((sum, amount, c) => sum + Math.min(amount, stock[c]) * VALUES[c], 0)
        : 0;
    return coverage * 2.6 + stockPotential(stock, goals) * 1.2 + weighted(stock) * .16 * params.capacityWeight;
}
/** 超额水晶迭代弃置：每颗都选择弃置后保留价值最高的颜色。 */
export function trimStock(source, goals, preferred, params) {
    const stock = cloneStock(source);
    const discarded = [];
    while (stockCount(stock) > 10) {
        let color = -1, best = -Infinity;
        for (let c = 0; c < 4; c++) {
            if (stock[c] === 0)
                continue;
            stock[c]--;
            const rating = keepValue(stock, goals, preferred, params);
            stock[c]++;
            if (rating > best) {
                best = rating;
                color = c;
            }
        }
        if (color < 0)
            throw new Error('超额水晶弃置失败');
        stock[color]--;
        discarded.push(color);
    }
    return { stock, discarded };
}
