    const synergy = card.kind === 'trade'
        ? card.input.reduce((n, amount, i) => n + Math.min(amount, supplied[i]) * VALUES[i], 0) / (weighted(card.input) + 1)
        : card.kind === 'create'
            ? engine.filter(c => c.kind === 'trade').reduce((n, c) => n + c.input.reduce((v, amount, i) => v + Math.min(amount, card.output[i]), 0), 0) * .18
            : .5;
