    { name: '引擎大师', engine: 1.3, tempo: 0.8, contest: 0.9 },
    { name: '速攻专家', engine: 0.7, tempo: 1.3, contest: 1.0 },
    { name: '精算大师', engine: 1.0, tempo: 1.0, contest: 1.0 },
