export function mulberry32(seed) {
    let value = seed >>> 0;
    return () => {
        value = (value + 0x6D2B79F5) | 0;
        let t = Math.imul(value ^ (value >>> 15), 1 | value);
        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
