    const id = g.golemMarket[a.index];
    const card = GOLEM_BY_ID[id];
    requireThat(has(p.stock, card.cost), '商队水晶不足，无法认领该魔像');
    p.stock = add(p.stock, card.cost, -1);
    p.claimed.push(id);
