    if (a.index === 0 && g.copper > 0) {
        g.copper--;
        p.copper++;
        coin = '、获得铜币 3 分';
    }
    else if (a.index === 0 && g.copper === 0 && g.silver > 0) {
        g.silver--;
        p.silver++;
        coin = '、获得银币 1 分';
    }
    else if (a.index === 1 && g.copper > 0 && g.silver > 0) {
        g.silver--;
        p.silver++;
        coin = '、获得银币 1 分';
