    g.golemMarket.splice(a.index, 1);
    drawGolem(g);
    record(g, `${p.name} 认领 ${card.points} 分魔像${coin}`);
    const target = g.players.length >= 4 ? 5 : 6;
    if (p.claimed.length >= target && g.triggerPlayer === null) {
        g.triggerPlayer = g.current;
