/** 联合规划决策入口（训练/评测/未来网页实验路径共用）。
 * 信息边界：完整 Game 仅用于构造 AIObservation 与合法性复核；
 * 决策本体只消费公开观察。 */
export function chooseJointAction(game, options) {
