        variant: String(merged.variant),
        championStructure: String(merged.championStructure),
        championParametersId: championParameters.id,
        acquisitionVariant: championParameters.acquisitionVariant ?? null,
        profileName: profileName ?? null,
        budgetMode: workUnits !== null ? 'fixed-work' : budgetMs !== null ? 'wall-clock' : 'wall-clock',
        budgetMs,
        workUnits,
        simSeed: typeof options.simSeed === 'number' ? options.simSeed : 0,
        horizon: Number(merged.horizon),
        worlds: Number(merged.worlds),
        opponentMode: String(merged.opponentMode),
        evaluator: String(merged.evaluator),
        gateMode: String(merged.gateMode),
        contestThreshold: Number(merged.contestThreshold),
        candidateCap: Number(merged.candidateCap),
        overrideMargin: Number(merged.overrideMargin),
        claimRanking: String(merged.claimRanking),
        nearTerminalCandidate: String(merged.nearTerminalCandidate),
        screenGoalScope: String(merged.screenGoalScope),
        batchAdmission: String(merged.batchAdmission),
        endgameSolver: String(merged.endgameSolver),
        endgameDiscard: Boolean(merged.endgameDiscard),
        arbitration: String(merged.arbitration),
        minPairedTrials: Number(merged.minPairedTrials),
        pairedZ: merged.pairedZ == null ? null : Number(merged.pairedZ),
        claimProtection: Boolean(merged.claimProtection),
        claimProtectDelta: Number(merged.claimProtectDelta),
        claimProtectMargin: Number(merged.claimProtectMargin),
        ensureBestClaimCandidate: Boolean(merged.ensureBestClaimCandidate),
        engineModel: championParameters.engineModel ?? 'v1',
        seatPolicy: championParameters.seatPolicy ?? 'flat',
        preset,
        overrides: Object.fromEntries(PRESET_FIELDS.filter(k => options[k] !== undefined).map(k => [k, options[k]])),
    };
}
/** 32 位 FNV-1a（确定性、零依赖；用于配置身份，不作为密码学哈希）。 */
export function fnv1a32(text) {
    let hash = 0x811c9dc5;
    for (let i = 0; i < text.length; i++) {
        hash ^= text.charCodeAt(i);
        hash = Math.imul(hash, 0x01000193) >>> 0;
    }
    return hash.toString(16).padStart(8, '0');
}
/** 稳定序列化（键排序；数组保持顺序）。 */
export function stableStringify(value) {
    if (Array.isArray(value))
        return `[${value.map(stableStringify).join(',')}]`;
    if (value && typeof value === 'object') {
        return `{${Object.keys(value).sort()
            .map(k => `${JSON.stringify(k)}:${stableStringify(value[k])}`).join(',')}}`;
    }
    return JSON.stringify(value);
}
/** 有效配置哈希（忽略可能已附加的 hash 字段，保证可重复计算）。 */
export function jointConfigHash(config) {
    const { hash: _ignored, ...payload } = config;
    return fnv1a32(stableStringify(payload));
}

/** 终局精确求解（AI7 任务 C1；只消费公开观察）。
 *
 * 动机（审计 §5.1 / §5.7，`TS-3P-FIN-003`）：
 * - 终局触发后，当前席位本局只剩**最后一次行动**（终局圈在本轮结束后结算），
 *   但冠军束搜索仍按"未来还能建设引擎/继续转换目标"的静态价值排序，
 *   把最后一手用于为下一次（不存在的）行动做准备；
 * - 官方计分 = 魔像分 + 铜币×3 + 银币×1 + **非黄水晶每颗 1 分**（黄 0 分），
 *   静态水晶价值（黄1/绿2/蓝3/粉4）不是终局残值；
 * - 容量溢出弃置在终局圈同样应按"最终得分最大"选择，而不是按中期目标缺口。
 *
 * 本模块做三件可精确证明的事（全部只用 AIObservation 公开信息）：
 * 1. `finalScoreOfAction`：对单个合法根行动计算**当前席位最终官方得分**
 *    （含认领得分/硬币、创造/升级/交易的净非黄变化、获取支付与卡面奖励、
 *    以及强制弃置的终局最优口径）；
 * 2. `opponentOneActionUpperBound`：对**尚未行动**的每个对手，计算其在本轮
 *    唯一一次行动中可能取得的得分增益上界（公开手牌/库存/市场），绝不假设
 *    对手不行动；
 * 3. `solveFinalAction`：按"保证名次优先、最终得分次之、乐观名次与目标封锁
 *    再次之"的字典序选择行动，并披露每个候选的精确得分与名次界。
 *
 * 名义边界：对手上界只使用**当前公开市场**（补牌顺序不可见，不用未翻开牌库
 * 猜测）；因此 `guaranteedRank` 是"公开信息 + 对手单动作上界"下的保守名次，
 * 不是含未知补牌的完整极小极大证明。该口径在返回值中显式披露。
 *
 * 禁止：硬编码具体对局/回合/卡 ID/席位；不读取隐藏牌库；不改变非终局决策。
 */
import { count, has, tradeLimit } from '../engine.js';
import { GOLEM_BY_ID, MERCHANT_BY_ID } from '../data.js';
const color = (c) => Number.isInteger(c) && c >= 0 && c <= 3;
/** 终局触发后，当前席位的下一次行动就是本局最后一次（终局圈在本轮结束结算）。 */
export function isFinalOwnAction(view) {
    return view.phase === 'turn' && view.triggerPlayer !== null;
}
/** 终局最优弃置：非黄每颗 1 分、黄 0 分 ⇒ 先弃黄，再按颜色升序弃非黄。
 * 只用于终局圈（此时该席位不会再有行动，任何非黄留存都严格优于黄）。 */
export function endgameDiscardColors(stock, excess) {
    if (!Number.isSafeInteger(excess) || excess < 0)
        throw new Error(`非法弃置数量：${String(excess)}`);
    const remaining = [...stock];
    if (count(remaining) < excess)
        throw new Error(`库存不足以弃置 ${excess} 颗`);
    const colors = [];
    for (let c = 0; c < 4 && colors.length < excess; c++) {
        while (remaining[c] > 0 && colors.length < excess) {
            remaining[c] -= 1;
            colors.push(c);
        }
    }
    return colors;
}
function officialScoreOf(player, stock) {
    const golemPoints = player.claimed.reduce((sum, id) => sum + (GOLEM_BY_ID[id]?.points ?? 0), 0);
    return golemPoints + player.copper * 3 + player.silver
        + stock.slice(1).reduce((sum, x) => sum + x, 0);
}
/** 认领 0/1 号位的硬币奖励（与 engine.applyClaim 逐条一致）。 */
function claimCoin(index, copperPool, silverPool) {
    if (index === 0 && copperPool > 0)
        return { coin: 3, copper: 1, silver: 0 };
    if (index === 0 && copperPool === 0 && silverPool > 0)
        return { coin: 1, copper: 0, silver: 1 };
    if (index === 1 && copperPool > 0 && silverPool > 0)
        return { coin: 1, copper: 0, silver: 1 };
    return { coin: 0, copper: 0, silver: 0 };
}
/** 单行动后的当前席位最终得分（精确、公开信息）。非法行动返回 null。 */
export function finalScoreOfAction(view, action) {
    if (!isFinalOwnAction(view))
        return null;
    const me = view.players[view.playerId];
    if (!me || view.current !== view.playerId)
        return null;
    let stock = [...me.stock];
    const claimed = [...me.claimed];
    let copper = me.copper;
    let silver = me.silver;
    if (action.type === 'claim') {
        const id = view.golemMarket[action.index];
        const golem = id ? GOLEM_BY_ID[id] : null;
        if (!golem || !has(stock, golem.cost))
            return null;
        for (let c = 0; c < 4; c++)
            stock[c] -= golem.cost[c];
        const reward = claimCoin(action.index, view.copper, view.silver);
        copper += reward.copper;
        silver += reward.silver;
        claimed.push(id);
    }
    else if (action.type === 'play') {
        const card = MERCHANT_BY_ID[action.cardId];
        if (!card || !me.hand.includes(action.cardId))
            return null;
        if (card.kind === 'create') {
            if (action.steps?.length || action.repeats !== undefined)
                return null;
            const out = card.output;
            for (let c = 0; c < 4; c++)
                stock[c] += out[c];
        }
        else if (card.kind === 'upgrade') {
            const steps = action.steps ?? [];
            if (action.repeats !== undefined || steps.length > card.steps)
                return null;
            for (const source of steps) {
                if (!color(source) || source >= 3 || stock[source] <= 0)
                    return null;
                stock[source] -= 1;
                stock[source + 1] += 1;
            }
        }
        else {
            const repeats = action.repeats ?? 1;
            const limit = tradeLimit(stock, action.cardId);
            if (!Number.isSafeInteger(repeats) || repeats < 1 || repeats > limit)
                return null;
            for (let i = 0; i < repeats; i++) {
                if (!has(stock, card.input))
                    return null;
                for (let c = 0; c < 4; c++)
                    stock[c] -= card.input[c];
                for (let c = 0; c < 4; c++)
                    stock[c] += card.output[c];
            }
        }
    }
    else if (action.type === 'acquire') {
        const offer = view.merchantMarket[action.index];
        if (!offer)
            return null;
        if (!Array.isArray(action.payment) || action.payment.length !== action.index)
            return null;
        for (const c of action.payment) {
            if (!color(c) || stock[c] <= 0)
                return null;
            stock[c] -= 1;
        }
        for (let c = 0; c < 4; c++)
            stock[c] += offer.bonus[c];
    }
    else if (action.type === 'rest') {
        // 休息只收回已打出卡，不改库存与得分。
    }
    else {
        return null;
    }
    let discarded = [];
    if (count(stock) > 10) {
        discarded = endgameDiscardColors(stock, count(stock) - 10);
        for (const c of discarded)
            stock[c] -= 1;
    }
    return {
        action,
        ownFinalScore: officialScoreOf({ claimed, copper, silver }, stock),
        stockAfter: stock,
        discarded,
    };
}
/** 单个对手在本轮唯一一次行动中的**得分增益上界**（公开信息）。
 * 口径说明：
 * - 认领：市场当前可支付魔像的（分值 + 硬币 − 非黄费用）；
 * - 创造：非黄产出（受 10 颗容量约束，溢出按终局弃黄口径不影响非黄）；
 * - 升级：最多把 min(步数, 黄水晶数) 颗黄升成绿（+1/颗）；
 * - 交易：重复到 tradeLimit 的净非黄增益（受容量约束）；
 * - 获取：卡面奖励非黄 − 最小非黄支付（先用黄支付；受容量约束）；
 * - 其余行动 0。
 * 只使用当前公开市场（对手认领后补牌未知，不猜测）。 */
export function opponentOneActionUpperBound(opponent, view, golemMarket, copperPool, silverPool) {
    const stock = [...opponent.stock];
    const room = Math.max(0, 10 - count(stock));
    let best = 0;
    for (let index = 0; index < golemMarket.length; index++) {
        const golem = GOLEM_BY_ID[golemMarket[index]];
        if (!golem || !has(stock, golem.cost))
            continue;
        const reward = claimCoin(index, copperPool, silverPool);
        const gain = golem.points + reward.coin
            - golem.cost.slice(1).reduce((sum, x) => sum + x, 0);
        if (gain > best)
            best = gain;
    }
    const yellow = stock[0];
    for (const id of opponent.hand) {
        const card = MERCHANT_BY_ID[id];
        if (!card)
            continue;
        if (card.kind === 'create') {
            const gain = Math.min(room, card.output.slice(1).reduce((sum, x) => sum + x, 0));
            if (gain > best)
                best = gain;
        }
        else if (card.kind === 'upgrade') {
            const gain = Math.min(room, Math.min(card.steps, yellow));
            if (gain > best)
                best = gain;
        }
        else {
            const limit = tradeLimit(stock, id);
            const net = card.output.slice(1).reduce((sum, x) => sum + x, 0)
                - card.input.slice(1).reduce((sum, x) => sum + x, 0);
            if (net > 0) {
                const gain = Math.min(room, limit * net);
                if (gain > best)
                    best = gain;
            }
        }
    }
    for (let index = 0; index < view.merchantMarket.length; index++) {
        if (count(stock) < index)
            continue;
        const bonus = view.merchantMarket[index].bonus;
        const nonYellowPayment = Math.max(0, index - yellow);
        const gain = Math.min(room, bonus.slice(1).reduce((sum, x) => sum + x, 0) - nonYellowPayment);
        if (gain > best)
            best = gain;
    }
    return Math.max(0, best);
}
/** 官方名次比较：分数高者优先；平分时座位号大者（终局圈最后行动者）优先，
 * 与 engine.ranking 的 `score(b) − score(a) || b.id − a.id` 逐条一致。 */
function beatsUs(opponentSeat, opponentScore, mySeat, myScore) {
    if (opponentScore !== myScore)
        return opponentScore > myScore;
    return opponentSeat > mySeat;
}
/** 市场封锁值：本行动移除的、对手（本轮仍会行动且上界超过我们）可立即认领的最高分值。
 * 只在同等名次/得分时作为确定性次级偏好，不改变主要目标。 */
function denialOf(beforeMarket, afterMarket, opponents, myScore, view) {
    const threats = opponents.filter(o => o.actsAfter && o.upper > myScore);
    let denied = 0;
    for (const id of beforeMarket) {
        if (afterMarket.includes(id))
            continue;
        if (!GOLEM_BY_ID[id])
            continue;
        for (const o of threats) {
            const p = view.players[o.seat];
            if (p && has(p.stock, GOLEM_BY_ID[id].cost)) {
                denied = Math.max(denied, GOLEM_BY_ID[id].points);
                break;
            }
        }
    }
    return denied;
}
/** 终局行动求解：枚举全部合法根行动，按字典序选择。
 *
 * 排序（确定性）：
 * 1. 保证名次升序（对手单动作上界下的最差名次）；
 * 2. 最终官方得分降序；
 * 3. 乐观名次升序（对手不行动时的名次，作为更接近实际的次级偏好）；
 * 4. 市场封锁值降序（同等条件下拿走对手可用的高分魔像）；
 * 5. 行动键升序（稳定）。
 *
 * 严格优于"静态目标价值"：得分是精确规则结算，名次按官方平分规则，
 * 且对仍会行动的对手使用上界而不是假设其不行动。 */
export function solveFinalAction(view, legalActions) {
    if (!isFinalOwnAction(view))
        return null;
    const candidates = [];
    for (const action of legalActions) {
        const scored = finalScoreOfAction(view, action);
        if (!scored)
            continue;
        const afterMarket = action.type === 'claim'
            ? view.golemMarket.filter((_, i) => i !== action.index)
            : view.golemMarket;
        // 我方认领会消耗公开硬币池：对手上界必须使用更新后的池。
        let copperPool = view.copper;
        let silverPool = view.silver;
        if (action.type === 'claim') {
            const reward = claimCoin(action.index, view.copper, view.silver);
            copperPool -= reward.copper;
            silverPool -= reward.silver;
        }
        const opponents = view.players.map(p => {
            if (p.id === view.playerId) {
                return { seat: p.id, current: scored.ownFinalScore, upper: scored.ownFinalScore, actsAfter: false, maxGain: 0 };
            }
            const current = officialScoreOf(p, p.stock);
            const actsAfter = p.id > view.playerId;
            const maxGain = actsAfter
                ? opponentOneActionUpperBound(p, view, afterMarket, copperPool, silverPool)
                : 0;
            return { seat: p.id, current, upper: current + maxGain, actsAfter, maxGain };
        });
        let guaranteedRank = 1;
        let optimisticRank = 1;
        for (const o of opponents) {
            if (o.seat === view.playerId)
                continue;
            if (beatsUs(o.seat, o.upper, view.playerId, scored.ownFinalScore))
                guaranteedRank += 1;
            if (beatsUs(o.seat, o.current, view.playerId, scored.ownFinalScore))
                optimisticRank += 1;
        }
        candidates.push({
            ...scored,
            guaranteedRank,
            optimisticRank,
            denial: denialOf(view.golemMarket, afterMarket, opponents, scored.ownFinalScore, view),
        });
    }
    if (!candidates.length)
        return null;
    const rankKey = (a) => JSON.stringify(a.action);
    candidates.sort((a, b) => a.guaranteedRank - b.guaranteedRank
        || b.ownFinalScore - a.ownFinalScore
        || a.optimisticRank - b.optimisticRank
        || b.denial - a.denial
        || rankKey(a).localeCompare(rankKey(b)));
    const best = candidates[0];
    const alternatives = candidates.slice(0, 5).map(c => ({
        action: c.action,
        ownFinalScore: c.ownFinalScore,
        guaranteedRank: c.guaranteedRank,
        optimisticRank: c.optimisticRank,
    }));
    // 对手界按座位序稳定输出（同分同 id 时保证可复现）。
    const bestAction = best.action;
    const bestClaimIndex = bestAction.type === 'claim' ? bestAction.index : null;
    const afterBestMarket = bestClaimIndex !== null
        ? view.golemMarket.filter((_, i) => i !== bestClaimIndex)
        : view.golemMarket;
    const finalOpponents = view.players.map(p => {
        if (p.id === view.playerId) {
            return { seat: p.id, current: best.ownFinalScore, upper: best.ownFinalScore, actsAfter: false, maxGain: 0 };
        }
        const current = officialScoreOf(p, p.stock);
        const actsAfter = p.id > view.playerId;
        let copperPool = view.copper;
        let silverPool = view.silver;
        if (bestClaimIndex !== null) {
            const reward = claimCoin(bestClaimIndex, view.copper, view.silver);
            copperPool -= reward.copper;
            silverPool -= reward.silver;
        }
        const maxGain = actsAfter
            ? opponentOneActionUpperBound(p, view, afterBestMarket, copperPool, silverPool)
            : 0;
        return { seat: p.id, current, upper: current + maxGain, actsAfter, maxGain };
    });
    return {
        action: best.action,
        ownFinalScore: best.ownFinalScore,
        guaranteedRank: best.guaranteedRank,
        optimisticRank: best.optimisticRank,
        discarded: best.discarded,
        stockAfter: best.stockAfter,
        opponents: finalOpponents,
        denial: best.denial,
        alternatives,
        rankModel: 'public-market-one-action-bound',
        evaluatedActions: candidates.length,
    };
}
/** 供测试/诊断使用：终局行动的精确最终得分表（无选择）。 */
export function finalScoreTable(view, legalActions) {
    const out = [];
    for (const action of legalActions) {
        const scored = finalScoreOfAction(view, action);
        if (scored)
            out.push(scored);
    }
    return out;
}

/** 联合搜索的叶子评价器分层（AI6 第四阶段·任务 D）。
 *
 * 目标量：P(当前玩家最终排名第一 | 状态, 对手模型) 的近似。
 * - 真实到达终局的轨迹：直接用正式规则结算（engine.ranking 语义），
 *   value = 1（第一名）/ 0（其余）——绝不用启发式替代；
 * - 未到终局的叶子：L0–L3 分层评价器输出 (0,1) 的胜率近似（logistic 映射），
 *   层级间严格分离且全部显式标注口径。
 *
 * 诚实性边界（任务 D）：资源估值/分差永远不直接称为"真实获胜概率"；
 * L3 的校准映射由离线脚本（training/joint/calibrate.mjs）在独立种子块上
 * 拟合并写入 l3-calibration.ts；无校准权重时自动回落 L2 并在结果中披露。
 *
 * 价值向量区分玩家（任务 D）：LeafVector 按席位逐玩家给出
 * [score, claimed, engine, crystals]，标量化只发生在明确的比较维度上，
 * 绝不把全部对手合并成一个负效用项。
 */
import { GOLEM_BY_ID } from '../data.js';
import { score as engineScore } from '../engine.js';
import { reachableStockOf } from './simview.js';
import { VALUES, weighted } from '../ai/knowledge.js';
import { L3_CALIBRATION } from './l3-calibration.js';
/** logistic 映射：原始 margin → (0,1) 胜率近似。尺度参数（分差尺度 8 分 ≈
 * 一张中档魔像）为 L3 校准前的默认口径；L3 校准时由数据重估。 */
export function logisticWin(margin, scale = 8) {
    return 1 / (1 + Math.exp(-margin / scale));
}
export function leafVector(state, mySeat) {
    const players = state.players;
    const score = players.map(p => engineScore(p));
    const claimed = players.map(p => p.claimed.length);
    const engine = players.map(p => p.hand.length + p.played.length);
    const crystals = players.map(p => weighted(p.stock));
    const golems = state.golemMarket.map(id => {
        const goal = GOLEM_BY_ID[id];
        const total = goal ? weighted(goal.cost) : 0;
        const coverageOf = (seat) => {
            if (!goal)
                return 0;
            const reach = reachableStockOf(players[seat].stock, players[seat].hand);
            const covered = goal.cost.reduce((s, n, c) => s + Math.min(n, reach[c]) * VALUES[c], 0);
            return total > 0 ? covered / total : 0;
        };
        const myCoverage = coverageOf(mySeat);
        let maxRivalCoverage = 0;
        for (const p of players) {
            if (p.id === mySeat)
                continue;
            maxRivalCoverage = Math.max(maxRivalCoverage, coverageOf(p.id));
        }
        return { id, points: goal?.points ?? 0, myCoverage, maxRivalCoverage };
    });
    return { seats: players.map(p => p.id), score, claimed, engine, crystals, golems, triggerPlayer: state.triggerPlayer, turnNumber: state.turnNumber };
}
function maxOther(values, mySeat, seats) {
    let max = -Infinity;
    for (let i = 0; i < values.length; i++) {
        if (seats[i] === mySeat)
            continue;
        if (values[i] > max)
            max = values[i];
    }
    return Number.isFinite(max) ? max : 0;
}
/** L0：当前冠军启发式口径——纯得分差（冠军 routeGrade 的核心信号）。 */
export function evaluateL0(v, mySeat) {
    const my = v.score[v.seats.indexOf(mySeat)] ?? 0;
    return logisticWin(my - maxOther(v.score, mySeat, v.seats));
}
/** L1：相对分数 + 已认领魔像 + 资源状态的多人向量估值（logistic 压缩）。 */
export function evaluateL1(v, mySeat) {
    return logisticWin(l1RawMargin(v, mySeat));
}
/** L1 原始 margin（多人向量标量化；权重显式披露）。 */
export function l1RawMargin(v, mySeat) {
    const i = v.seats.indexOf(mySeat);
    return (v.score[i] - maxOther(v.score, mySeat, v.seats))
        + 0.35 * (v.claimed[i] - maxOther(v.claimed, mySeat, v.seats))
        + 0.12 * (v.engine[i] - maxOther(v.engine, mySeat, v.seats))
        + 0.08 * (v.crystals[i] - maxOther(v.crystals, mySeat, v.seats));
}
/** L2 原始 margin：L1 + 目标竞争覆盖优势 + 终局时间压力（静态公开模型，
 * 不做 Monte Carlo——ETA/Survival 级别的昂贵预测只允许在根节点使用）。
 * - 市场魔像：我的可达覆盖 − 最强对手覆盖，按分值 0.10 加权；
 * - 终局风险：他人触发终局时，领先 +0.5 / 落后 −0.8（终局结算临近）；
 * - 硬币池：领先者对 0/1 号位认领奖励的边际通道。 */
export function l2RawMargin(v, mySeat, copperPool, silverPool) {
    const i = v.seats.indexOf(mySeat);
    const myScore = v.score[i];
    const maxOpp = maxOther(v.score, mySeat, v.seats);
    let margin = l1RawMargin(v, mySeat);
    for (const g of v.golems) {
        margin += (g.myCoverage - g.maxRivalCoverage) * g.points * 0.10;
    }
    if (v.triggerPlayer !== null)
        margin += myScore >= maxOpp ? 0.5 : -0.8;
    margin += (myScore >= maxOpp ? 0.08 : 0) * Math.min(4, copperPool + 0.5 * silverPool);
    return margin;
}
/** L2：L1 + 竞争与终局增强（logistic 压缩）。 */
export function evaluateL2(v, mySeat, copperPool, silverPool) {
    return logisticWin(l2RawMargin(v, mySeat, copperPool, silverPool));
}
/** L3：独立校准的胜率近似（分段线性 P(first | L2 raw margin)）。
 * 无校准权重时回落 L2（在 stats/报告披露）。 */
export function evaluateL3(v, mySeat, copperPool, silverPool, calibration) {
    if (!calibration || !calibration.valid)
        return evaluateL2(v, mySeat, copperPool, silverPool);
    const raw = l2RawMargin(v, mySeat, copperPool, silverPool);
    const { knots, values } = calibration.mapping;
    if (raw <= knots[0])
        return values[0];
    if (raw >= knots[knots.length - 1])
        return values[values.length - 1];
    for (let i = 1; i < knots.length; i++) {
        if (raw <= knots[i]) {
            const t = (raw - knots[i - 1]) / (knots[i] - knots[i - 1] || 1);
            return values[i - 1] + t * (values[i] - values[i - 1]);
        }
    }
    return values[values.length - 1];
}
/** 评价器主入口。finished → 正式规则第一名判定；否则按层级。 */
export function evaluateLeaf(state, finished, mySeat, level, firstPlaceOf) {
    if (finished)
        return firstPlaceOf(state, mySeat) ? 1 : 0;
    const v = leafVector(state, mySeat);
    switch (level) {
        case 'L0': return evaluateL0(v, mySeat);
        case 'L1': return evaluateL1(v, mySeat);
        case 'L2': return evaluateL2(v, mySeat, state.copper, state.silver);
        case 'L3': return evaluateL3(v, mySeat, state.copper, state.silver, L3_CALIBRATION);
    }
}

/** Joint Rollout：真实多人行动时序的联合模拟（AI6 第四阶段·任务 B + C）。
 *
 * 这是本阶段最高优先级任务的落地核心。旧 Beam Search 的推演序列是
 * "我→我→我→我"（纯单代理）；本模块的推演序列是：
 *
 *   我行动 → 下家行动 → 其余玩家按座位行动 → 轮到我再次行动 → ……
 *   → 真实终局 或 视野上限叶子
 *
 * 结构保证（逐条对应任务 B 要求）：
 * 1. 每位玩家只在自己的合法行动节点行动（循环以 sim.view.current 分派）；
 * 2. 对手行动由 Opponent Model V1 采样 / 规则 / 均匀三种模式生成（opponents.ts）；
 * 3. 所有行动经 PublicSimulation.step 精确推进（differential 锚定正式引擎）；
 * 4. 对手认领后目标立即从市场消失（transition.applyClaim 语义，测试强制）；
 * 5. 市场补牌由独立 Belief Sampler 队列处理（root 采样一次，分支共享 = CRN）；
 * 6. 市场变化后我的策略逐决策点重新计算（myRankedActions 每次重入）；
 * 7. 对手提前触发终局被自然处理（finishAction 整轮结算 → finished）；
 * 8. 我只在 current === mySeat 时插入行动——绝不在失去行动机会后继续规划；
 * 9. 轨迹内公共目标竞争相互依赖（同一市场状态，认领互斥）。
 */
import { ranking, count } from '../engine.js';
import { GOLEM_BY_ID } from '../data.js';
import { mulberry32 } from '../sim/rng.js';
import { heuristicContext, myRankedActions, discardDecision } from './rollout-policy.js';
import { endgameDiscardColors } from './endgame.js';
import { createOpponentContext, sampleOpponentAction, describe, familyOf } from './opponents.js';
import { evaluateLeaf } from './evaluators.js';
import { PressureCache, profileByName } from './simview.js';
import { CHAMPION_PARAMETERS } from '../ai/parameters.js';
/** 正式规则第一名判定（engine.ranking 平分语义复用）。 */
export function firstPlaceOf(state, seat) {
    const pseudoGame = { players: state.players };
    return ranking(pseudoGame)[0]?.id === seat;
}
/** 市场事件差分采集：step 前后魔像/商人市场对比。 */
function collectEvents(before, after, transition, sink) {
    const actor = before.current;
    for (const id of before.golemMarket) {
        if (!after.golemMarket.includes(id)) {
            sink.push({ transition, kind: 'claim', seat: actor, golemId: id });
        }
    }
    for (const m of before.merchantMarket) {
        if (!after.merchantMarket.some(x => x.id === m.id)) {
            sink.push({ transition, kind: 'refill', seat: actor, merchantId: m.id });
        }
    }
}
/** 从指定模拟状态推进一条完整联合轨迹到终局或视野上限。
 * sim 调用方持有（root 分支或 tree 节点分支）；本函数继续推进并就地修改。 */
export function playJointTrajectory(sim, rng, ctx) {
    const mode = ctx.mode;
    const om = ctx.om;
    const opponentCtx = createOpponentContext(mode, om);
    const pressureCache = new PressureCache();
    let transitions = 0;
    let opponentMeta = null;
    while (!sim.finished && transitions < ctx.horizon) {
        if (ctx.deadline !== undefined && performance.now() > ctx.deadline)
            break;
        const state = sim.view;
        const actor = state.current;
        // 任务 B.8：行动者只可能是当前席位——己方分支以 current === mySeat 判定，
        // 绝不在失去行动机会后插入规划行动。
        let action = null;
        if (actor === ctx.mySeat) {
            if (state.phase === 'overflow') {
                const stock = state.players[actor].stock;
                action = ctx.endgameDiscard && state.triggerPlayer !== null
                    ? { type: 'discard', colors: endgameDiscardColors(stock, count(stock) - 10) }
                    : { type: 'discard', colors: discardDecision(stock, state.golemMarket, CHAMPION_PARAMETERS) };
            }
            else {
                const ctxH = heuristicContext(state, ctx.params ?? CHAMPION_PARAMETERS, profileByName(ctx.profileName), pressureCache);
                const ranked = myRankedActions(state, actor, ctxH).ranked;
                action = ranked[0]?.action ?? { type: 'rest' };
            }
        }
        else {
            const sample = sampleOpponentAction(state, rng, opponentCtx, ms => { ctx.omTimeMs && (ctx.omTimeMs.value += ms); });
            action = sample?.action ?? { type: 'rest' };
            if (sample)
                opponentMeta = { family: sample.family, p: sample.p, label: sample.label };
        }
        if (!action)
            break;
        const events = ctx.events;
        const actorLog = ctx.actorLog;
        const stepLog = ctx.stepLog;
        const logEntry = () => {
            if (!actorLog)
                return;
            actorLog.push(opponentMeta
                ? { seat: actor, action, transition: transitions, family: opponentMeta.family, p: opponentMeta.p, label: opponentMeta.label }
                : { seat: actor, action, transition: transitions, family: familyOf(action), label: describe(action) });
        };
        if (events && transitions < 400) {
            const before = sim.view;
            try {
                logEntry();
                sim.step(action);
                collectEvents(before, sim.view, transitions, events);
            }
            catch {
                // 理论不可达（行动均来自合法枚举）；防御性终止轨迹并按叶子计价。
                break;
            }
        }
        else {
            try {
                logEntry();
                sim.step(action);
            }
            catch {
                break;
            }
        }
        stepLog?.push({ seat: actor, action });
        transitions += 1;
        opponentMeta = null;
    }
    const finished = sim.finished;
    const value = evaluateLeaf(sim.view, finished, ctx.mySeat, ctx.evaluator, firstPlaceOf);
    const finalRank = finished ? (firstPlaceOf(sim.view, ctx.mySeat) ? 1 : (ranking({ players: sim.view.players }).findIndex(r => r.id === ctx.mySeat) + 1)) : null;
    return { value, transitions, finished, finalRank };
}
/** 试验随机流派生（PR #26 P1-1 修复：多世界采样 + Common Random Numbers）。
 * - world：信念世界索引（0..W-1）——不同 world = 不同未知牌序采样（多世界覆盖）；
 * - replica：同一世界内的对手采样重复索引。
 * 同一 (world, replica) 对跨根行动派生同一随机流 ⇒ 配对比较（CRN）：
 * 根行动间价值差来自行动本身而非对手/翻牌噪声。 */
export function trialRngSeed(simSeed, world, replica) {
    return ((simSeed >>> 0) ^ Math.imul(world + 1, 0x9E3779B9) ^ Math.imul(replica + 1, 0x85EBCA6B)) >>> 0;
}
/** 根行动联合评估：fork root → 执行根行动 → 推进联合轨迹。
 * world/replica 经 trialRngSeed 派生对手采样随机流（CRN 语义见上）。 */
export function runJointRollout(root, rootAction, world, replica, simSeed, ctx) {
    const branch = root.fork();
    branch.step(rootAction); // 根行动来自合法枚举；非法立即抛错（暴露缺陷）。
    const rng = mulberry32(trialRngSeed(simSeed, world, replica));
    return playJointTrajectory(branch, rng, ctx);
}
/** 魔像目标标签（轨迹输出）。 */
export function golemLabel(id) {
    return GOLEM_BY_ID[id] ? `${id}(${GOLEM_BY_ID[id].points}分)` : id;
}

/** Selective Joint Tree：关键己方决策点的选择性分支展开（AI6 第四阶段·任务 C）。
 *
 * PR #26 修复（P0-1 搜索树时序）后的结构：
 *
 *   根行动（我）→ [对手行动：概率模型采样，合法多人状态转移]
 *   → 轮到我 → expandMyNode（top-M 分支 max，仅当 current === mySeat）
 *   → 每个分支推进到我的下一个决策点 → 递归 / 启发式联合 rollout 续推
 *
 * 严格时序不变量（回归测试 tests/joint-pr26-regression.test.mjs 强制）：
 * 1. 己方分支展开只发生在 current === mySeat 的节点（v1 缺陷：根行动后未推进
 *    对手回合就直接展开"己方"分支——initialState 按 view.current 取行动者，
 *    实际展开的是对手的候选集，并以我方 leaf 价值取 max ⇒ 对手被最优化为我方行动）；
 * 2. 对手行动一律经 sampleOpponentAction 合法采样 + sim.step 精确转移；
 * 3. 溢出弃置按正式引擎语义（溢出回合不推进座位，弃置后 finishAction）；
 * 4. 兄弟分支持有独立预算计数（v1 缺陷：共享 transitions 计数使先探索的分支
 *    吃掉后续分支的视野，值依赖兄弟求值顺序）；
 * 5. 终局价值一律取正式规则 ranking（绝不用启发式替代）。
 */
import { ranking } from '../engine.js';
import { mulberry32 } from '../sim/rng.js';
import { heuristicContext, myRankedActions, discardDecision } from './rollout-policy.js';
import { createOpponentContext, sampleOpponentAction } from './opponents.js';
import { firstPlaceOf, trialRngSeed } from './joint-rollout.js';
import { evaluateLeaf } from './evaluators.js';
import { PressureCache, profileByName } from './simview.js';
import { CHAMPION_PARAMETERS } from '../ai/parameters.js';
/** 推进到我的下一个决策点（对手节点采样）或终局。返回是否到达我的决策点。 */
function advanceUntilMyTurn(sim, rng, ctx, budget) {
    const opponentCtx = createOpponentContext(ctx.mode, ctx.om);
    while (!sim.finished && sim.view.current !== ctx.mySeat) {
        if (budget.transitions >= ctx.horizon)
            return false;
        if (ctx.deadline !== undefined && performance.now() > ctx.deadline)
            return false;
        const state = sim.view;
        const actor = state.current;
        let action = null;
        if (state.phase === 'overflow') {
            // 溢出回合不推进座位（正式引擎 finishAction 语义）：弃置仍属当前玩家。
            action = { type: 'discard', colors: discardDecision(state.players[actor].stock, state.golemMarket, CHAMPION_PARAMETERS) };
        }
        else {
            const sample = sampleOpponentAction(state, rng, opponentCtx, ms => { ctx.omTimeMs && (ctx.omTimeMs.value += ms); });
            action = sample?.action ?? { type: 'rest' };
        }
        try {
            sim.step(action);
        }
        catch {
            return false;
        }
        ctx.stepLog?.push({ seat: actor, action });
        budget.transitions += 1;
        budget.totalTransitions += 1;
    }
    if (sim.finished)
        budget.reachedTerminal = true;
    return !sim.finished && sim.view.current === ctx.mySeat;
}
/** 己方决策节点展开（选择性分支 + 递归 max）。
 * 前置不变量：current === mySeat（内部防御性推进，违背即缺陷）。 */
function expandMyNode(sim, depthLeft, rng, ctx, budget) {
    if (sim.finished) {
        budget.reachedTerminal = true;
        return firstPlaceOf(sim.view, ctx.mySeat) ? 1 : 0;
    }
    if (budget.transitions >= ctx.horizon || (ctx.deadline !== undefined && performance.now() > ctx.deadline)) {
        return evaluateLeaf(sim.view, false, ctx.mySeat, ctx.evaluator, firstPlaceOf);
    }
    // P0-1 时序不变量的防御性自愈：未轮到我时先推进对手回合（正常路径由
    // advanceUntilMyTurn 保证；此分支仅捕获根调用/溢出后的遗漏情形）。
    if (sim.view.current !== ctx.mySeat) {
        if (!advanceUntilMyTurn(sim, rng, ctx, budget)) {
            return sim.finished
                ? (firstPlaceOf(sim.view, ctx.mySeat) ? 1 : 0)
                : evaluateLeaf(sim.view, false, ctx.mySeat, ctx.evaluator, firstPlaceOf);
        }
    }
    if (depthLeft <= 0) {
        // 叶子：启发式联合 rollout 续推（单条；对手继续采样）。
        return playTrajectoryFrom(sim, rng, ctx, budget);
    }
    const state = sim.view;
    // 溢出：强制弃置（单分支；弃置后座位推进，须先回到我的决策点再展开）。
    if (state.phase === 'overflow') {
        const action = { type: 'discard', colors: discardDecision(state.players[state.current].stock, state.golemMarket, CHAMPION_PARAMETERS) };
        const branch = sim.fork();
        try {
            branch.step(action);
        }
        catch {
            return evaluateLeaf(sim.view, false, ctx.mySeat, ctx.evaluator, firstPlaceOf);
        }
        ctx.stepLog?.push({ seat: state.current, action });
        budget.transitions += 1;
        budget.totalTransitions += 1;
        if (branch.finished) {
            budget.reachedTerminal = true;
            return firstPlaceOf(branch.view, ctx.mySeat) ? 1 : 0;
        }
        if (!advanceUntilMyTurn(branch, rng, ctx, budget)) {
            return branch.finished
                ? (firstPlaceOf(branch.view, ctx.mySeat) ? 1 : 0)
                : evaluateLeaf(branch.view, false, ctx.mySeat, ctx.evaluator, firstPlaceOf);
        }
        return expandMyNode(branch, depthLeft, rng, ctx, budget);
    }
    const ctxH = heuristicContext(state, CHAMPION_PARAMETERS, profileByName(ctx.profileName), new PressureCache());
    const ranked = myRankedActions(state, ctx.mySeat, ctxH).ranked;
    if (!ranked.length)
        return evaluateLeaf(sim.view, false, ctx.mySeat, ctx.evaluator, firstPlaceOf);
    const topM = ranked.slice(0, Math.max(1, ctx.treeBranching));
    let best = -Infinity;
    for (const candidate of topM) {
        // P0-1 修复：兄弟分支独立预算（共享计数会让先探索的分支吃掉后续分支视野，
        // 返回值依赖兄弟求值顺序）；totalTransitions 只作统计聚合。
        const siblingBudget = { transitions: 0, reachedTerminal: false, totalTransitions: budget.totalTransitions };
        const branch = sim.fork();
        try {
            branch.step(candidate.action);
        }
        catch {
            continue;
        }
        ctx.stepLog?.push({ seat: state.current, action: candidate.action });
        siblingBudget.transitions += 1;
        siblingBudget.totalTransitions += 1;
        let v;
        if (branch.finished) {
            siblingBudget.reachedTerminal = true;
            v = firstPlaceOf(branch.view, ctx.mySeat) ? 1 : 0;
        }
        else if (!advanceUntilMyTurn(branch, rng, ctx, siblingBudget)) {
            v = branch.finished
                ? (firstPlaceOf(branch.view, ctx.mySeat) ? 1 : 0)
                : evaluateLeaf(branch.view, false, ctx.mySeat, ctx.evaluator, firstPlaceOf);
        }
        else {
            v = expandMyNode(branch, depthLeft - 1, rng, ctx, siblingBudget);
        }
        budget.totalTransitions = Math.max(budget.totalTransitions, siblingBudget.totalTransitions);
        budget.reachedTerminal ||= siblingBudget.reachedTerminal;
        if (v > best)
            best = v;
    }
    if (best === -Infinity)
        return evaluateLeaf(sim.view, false, ctx.mySeat, ctx.evaluator, firstPlaceOf);
    return best;
}
/** 从当前状态续推启发式轨迹（tree 叶子；与 joint-rollout 同一循环语义）。 */
function playTrajectoryFrom(sim, rng, ctx, budget) {
    const opponentCtx = createOpponentContext(ctx.mode, ctx.om);
    const pressureCache = new PressureCache();
    while (!sim.finished && budget.transitions < ctx.horizon) {
        if (ctx.deadline !== undefined && performance.now() > ctx.deadline)
            break;
        const state = sim.view;
        const actor = state.current;
        let action = null;
        if (actor === ctx.mySeat) {
            if (state.phase === 'overflow') {
                action = { type: 'discard', colors: discardDecision(state.players[actor].stock, state.golemMarket, CHAMPION_PARAMETERS) };
            }
            else {
                const ctxH = heuristicContext(state, CHAMPION_PARAMETERS, profileByName(ctx.profileName), pressureCache);
                const ranked = myRankedActions(state, actor, ctxH).ranked;
                action = ranked[0]?.action ?? { type: 'rest' };
            }
        }
        else {
            const sample = sampleOpponentAction(state, rng, opponentCtx, ms => { ctx.omTimeMs && (ctx.omTimeMs.value += ms); });
            action = sample?.action ?? { type: 'rest' };
        }
        if (!action)
            break;
        try {
            sim.step(action);
        }
        catch {
            break;
        }
        ctx.stepLog?.push({ seat: actor, action });
        budget.transitions += 1;
        budget.totalTransitions += 1;
    }
    if (sim.finished)
        budget.reachedTerminal = true;
    return evaluateLeaf(sim.view, sim.finished, ctx.mySeat, ctx.evaluator, firstPlaceOf);
}
/** 根行动树评估（PR #26 修复后）：fork → 根行动 → 推进对手回合到我的决策点
 * → expandMyNode（treeDepth 层己方分支）。world/replica 语义同 runJointRollout。 */
export function runJointTreeTrial(root, rootAction, world, replica, simSeed, ctx) {
    const branch = root.fork();
    branch.step(rootAction);
    ctx.stepLog?.push({ seat: root.view.current, action: rootAction });
    const rng = mulberry32(trialRngSeed(simSeed, world, replica));
    const budget = { transitions: 1, reachedTerminal: false, totalTransitions: 1 };
    let value;
    if (branch.finished) {
        budget.reachedTerminal = true;
        value = firstPlaceOf(branch.view, ctx.mySeat) ? 1 : 0;
    }
    else if (!advanceUntilMyTurn(branch, rng, ctx, budget)) {
        // 未能在视野内回到我的决策点：终局取正式规则值，否则叶子估值。
        value = branch.finished
            ? (firstPlaceOf(branch.view, ctx.mySeat) ? 1 : 0)
            : evaluateLeaf(branch.view, false, ctx.mySeat, ctx.evaluator, firstPlaceOf);
    }
    else {
        value = expandMyNode(branch, Math.max(1, ctx.treeDepth), rng, ctx, budget);
    }
    // 终局名次用正式规则 ranking（P0-1 要求：绝不用启发式近似替代）。
    const finalRank = branch.finished
        ? ranking({ players: branch.view.players }).findIndex(r => r.id === ctx.mySeat) + 1
        : null;
    return { value, transitions: budget.totalTransitions, finished: budget.reachedTerminal, finalRank };
}

/** 临近终局候选覆盖（P1-C；只消费公开观察）。
 *
 * 动机（c83f C10）：临近终局时冠军束搜索可能继续走"高色后续潜力"路线，
 * 而正式得分（魔像分 + 铜币×3 + 银币 + 非黄水晶）当步最优的合法行动
 * 落在根先验第 6/48，未进入 candidateCap=4 —— 联合模拟根本没有机会评估它。
 *
 * 本模块只做两件可证伪的小事：
 * 1. risk：公开信息判断"下一手是否可能被任何席位（含自己）凑满第 5/6 张
 *    魔像而触发终局"——已触发，或任一席位已领 threshold−1 且当前付得起
 *    市场任一魔像；
 * 2. argmaxImmediate：对全部合法根行动计算**当步正式净分**（含铜银币、
 *    非黄水晶、升级产色、强制弃置），返回最大者。
 *
 * 禁止：硬编码具体对局/回合/卡 ID/人类席位；不把中局改成即时分贪心
 * （调用方只在 risk=true 且显式 nearTerminalCandidate≠off 时注入一个候选）。
 * 后继价值的最终裁决仍由联合模拟 + 保守覆盖完成，本模块不直接改选行动。
 */
import { count, has, tradeLimit } from '../engine.js';
import { GOLEM_BY_ID, MERCHANT_BY_ID } from '../data.js';
import { trimStock } from '../ai/evaluator.js';
import { CHAMPION_PARAMETERS } from '../ai/parameters.js';
/** 终局触发张数（与 engine.applyClaim 一致：>=4 人第 5 张，否则第 6 张）。 */
export function claimThreshold(playerCount) {
    return playerCount >= 4 ? 5 : 6;
}
function officialScoreOf(player, stock) {
    const golemPoints = player.claimed.reduce((sum, id) => sum + (GOLEM_BY_ID[id]?.points ?? 0), 0);
    return golemPoints + player.copper * 3 + player.silver + stock.slice(1).reduce((sum, x) => sum + x, 0);
}
/** 公开信息下的临近终局风险。 */
export function nearTerminalRisk(view) {
    const threshold = claimThreshold(view.players.length);
    if (view.triggerPlayer !== null) {
        return {
            risky: true, reason: 'already-triggered', threshold,
            threatenedSeats: view.players.map(p => p.id), selfThreatened: true,
        };
    }
    const threatenedSeats = [];
    for (const p of view.players) {
        if (p.claimed.length < threshold - 1)
            continue;
        const canPay = view.golemMarket.some(id => {
            const goal = GOLEM_BY_ID[id];
            return !!goal && has(p.stock, goal.cost);
        });
        if (canPay)
            threatenedSeats.push(p.id);
    }
    return {
        risky: threatenedSeats.length > 0,
        reason: threatenedSeats.length > 0 ? 'player-can-trigger' : null,
        threshold,
        threatenedSeats,
        selfThreatened: threatenedSeats.includes(view.playerId),
    };
}
/** 单个合法根行动的当步正式净分（等价于正式引擎该步 score 变化）。
 * 非法/不可确定（overflow 阶段 discard 等）返回 null。 */
export function immediateOfficialScoreDelta(view, action) {
    if (view.playerId !== view.current)
        return null;
    const me = view.players[view.playerId];
    if (!me)
        return null;
    let stock = [...me.stock];
    let copper = me.copper;
    let silver = me.silver;
    let delta = 0;
    let golemMarket = null;
    if (action.type === 'claim') {
        const id = view.golemMarket[action.index];
        const goal = id ? GOLEM_BY_ID[id] : null;
        if (!goal || !has(stock, goal.cost))
            return null;
        // 硬币奖励由**公开资源池**支付（engine.applyClaim 语义），不是玩家已持硬币。
        // 修复前本函数误用玩家自己的 copper/silver 判断资格：当玩家 0 铜但池中
        // 有铜时，认领净分会少算 3 分，直接影响认领保护门槛。
        let copperPool = view.copper;
        let silverPool = view.silver;
        let coin = 0;
        if (action.index === 0 && copperPool > 0) {
            copperPool -= 1;
            copper += 1;
            coin = 3;
        }
        else if (action.index === 0 && copperPool === 0 && silverPool > 0) {
            silverPool -= 1;
            silver += 1;
            coin = 1;
        }
        else if (action.index === 1 && copperPool > 0 && silverPool > 0) {
            silverPool -= 1;
            silver += 1;
            coin = 1;
        }
        delta += goal.points + coin;
        delta -= goal.cost.slice(1).reduce((sum, x) => sum + x, 0);
        for (let c = 0; c < 4; c++)
            stock[c] -= goal.cost[c];
        golemMarket = view.golemMarket.filter((_, i) => i !== action.index);
    }
    else if (action.type === 'play') {
        const card = MERCHANT_BY_ID[action.cardId];
        if (!card || !me.hand.includes(action.cardId))
            return null;
        if (card.kind === 'create') {
            if (action.steps?.length || action.repeats !== undefined)
                return null;
            const out = card.output;
            for (let c = 0; c < 4; c++)
                stock[c] += out[c];
            delta += out.slice(1).reduce((sum, x) => sum + x, 0);
        }
        else if (card.kind === 'upgrade') {
            const steps = action.steps ?? [];
            if (action.repeats !== undefined || steps.length > card.steps)
                return null;
            for (const source of steps) {
                if (!Number.isInteger(source) || source < 0 || source >= 3)
                    return null;
                if (stock[source] <= 0)
                    return null;
                stock[source] -= 1;
                stock[source + 1] += 1;
                // 黄→绿 +1 分；非黄→非黄净 0；黄最多 3 步（引擎限制）。
                if (source === 0)
                    delta += 1;
            }
        }
        else {
            const repeats = action.repeats ?? 1;
            const limit = tradeLimit(stock, action.cardId);
            if (!Number.isSafeInteger(repeats) || repeats < 1 || repeats > limit)
                return null;
            for (let i = 0; i < repeats; i++) {
                if (!has(stock, card.input))
                    return null;
                for (let c = 0; c < 4; c++)
                    stock[c] -= card.input[c];
                for (let c = 0; c < 4; c++)
                    stock[c] += card.output[c];
            }
            delta += repeats * (card.output.slice(1).reduce((sum, x) => sum + x, 0)
                - card.input.slice(1).reduce((sum, x) => sum + x, 0));
        }
    }
    else if (action.type === 'acquire') {
        const offer = view.merchantMarket[action.index];
        if (!offer)
            return null;
        if (!Array.isArray(action.payment) || action.payment.length !== action.index)
            return null;
        for (const color of action.payment) {
            if (!Number.isInteger(color) || color < 0 || color >= 4 || stock[color] <= 0)
                return null;
            stock[color] -= 1;
            if (color > 0)
                delta -= 1; // 非黄水晶离手 → 正式分 −1
        }
        for (let c = 0; c < 4; c++)
            stock[c] += offer.bonus[c];
        delta += offer.bonus.slice(1).reduce((sum, x) => sum + x, 0);
    }
    else if (action.type === 'rest') {
        // 休息只收回已打出卡，不改库存与得分。
    }
    else {
        return null;
    }
    let discarded = 0;
    if (count(stock) > 10) {
        // 溢出必须弃置；用冠军 trimStock 口径估算（公开信息 + 冻结参数）。
        const trimmed = trimStock(stock, golemMarket ?? view.golemMarket, null, CHAMPION_PARAMETERS);
        discarded = trimmed.discarded.length;
        delta -= trimmed.discarded.filter(c => c > 0).length;
        stock = trimmed.stock;
    }
    return { action, delta, scoreAfter: officialScoreOf({ ...me, copper, silver }, stock), discarded };
}
/** 全部合法根行动中当步正式净分最大者；仅在 delta>0 时返回（否则没有任何
 * "保留分"价值可保护）。平局按枚举顺序（认领先于打出/休息/获取）稳定取首个。 */
export function maxImmediateScoreAction(view, actions) {
    let best = null;
    for (const action of actions) {
        const candidate = immediateOfficialScoreDelta(view, action);
        if (!candidate || candidate.delta <= 0)
            continue;
        if (!best || candidate.delta > best.delta)
            best = candidate;
    }
    return best;
}

/** 联合搜索的对手行动策略（AI6 第四阶段·任务 B.2 + 任务 E）。
 *
 * 三种模式（任务 E：至少三种模式）：
 * - random：全量合法行动（等价去重后）均匀采样——信息公平的行为基线；
 * - rule：对手按自身进度效用贪心决策（ NEUTRAL 人格 + 冠军启发式候选集的
 *   轻量变体），softmax 温度采样保留多样性——每个对手只优化自己的局面，
 *   绝不实现"针对当前玩家的敌对联盟"（任务书 §任务 B 特别注意项）；
 * - om-v1：Opponent Model V1 predictAction 分布采样；模型内部按状态键 LRU
 *   缓存（任务 E.2），轨迹内重复状态不重复计费。
 *
 * 成本纪律（任务 E）：本模块绝不调用 predictClaimETA / predictSurvival
 * 的完整 Monte Carlo——ETA/Survival 只允许在根节点风险评估（planner.ts）
 * 与选择性预算分配中使用。轨迹内对手节点只消费轻量行动分布。
 */
import { enumerateLegalActions } from '../sim/legal.js';
import { NEUTRAL_PROFILE } from '../ai/profiles.js';
import { CHAMPION_PARAMETERS } from '../ai/parameters.js';
import { discardDecision, myRankedActions, heuristicContext } from './rollout-policy.js';
/** 创建对手上下文（参数固定为冻结冠军参数集——对手策略与候选 AI 共享同一
 * 启发式基线，保证消融对照只改变"对手行为来源"这一个因子）。
 * 温度 0.2：近确定性贪心而保留少量行为方差（τ=0.6→0.35→0.2 实测递减单轨迹
 * 叶值方差；CRN 配对下根行动间差异的信噪比随之上升）。 */
export function createOpponentContext(mode, om) {
    return { mode, om, temperature: 0.2, params: CHAMPION_PARAMETERS };
}
/** 对手溢出弃置：所有模式统一走冠军 trimStock 口径（强制行动，选择空间小，
 * 三模式分支无行为差异——在代码与报告中的显式口径声明）。 */
function opponentDiscard(state) {
    const player = state.players[state.current];
    return { type: 'discard', colors: discardDecision(player.stock, state.golemMarket, CHAMPION_PARAMETERS) };
}
/** 规则对手的轻量候选集：在冠军候选生成之上做成本压缩——
 * acquire 每槽位只保留 keepValue 最优的 1 个支付（冠军口径 top-3），
 * 升级变体保留 ≤2 个。剪枝仅作用于对手轨迹内策略（非根行动可达性）。 */
function ruleOpponentRanked(state, ctx) {
    const actorCtx = heuristicContext(state, ctx.params, NEUTRAL_PROFILE);
    const ranked = myRankedActions(state, state.current, actorCtx).ranked;
    // 每个市场槽位只保留最优 acquire；其余类型全保留（认领/打牌/休息）。
    const seenSlots = new Set();
    const out = [];
    for (const entry of ranked) {
        if (entry.action.type === 'acquire') {
            if (seenSlots.has(entry.action.index))
                continue;
            seenSlots.add(entry.action.index);
        }
        out.push(entry);
    }
    return out;
}
/** softmax 采样（logit 数组；确定性给定 rng）。 */
function softmaxSample(logits, temperature, rng) {
    const max = Math.max(...logits);
    const weights = logits.map(l => Math.exp((l - max) / Math.max(0.05, temperature)));
    const total = weights.reduce((s, w) => s + w, 0);
    let pick = rng() * total;
    for (let i = 0; i < weights.length; i++) {
        pick -= weights[i];
        if (pick <= 0)
            return i;
    }
    return weights.length - 1;
}
/** 从行动分布采样（分布条目携带 p；rng 确定性）。 */
function sampleDistribution(entries, rng) {
    let total = 0;
    for (const e of entries)
        total += e.p;
    if (!(total > 0))
        return null;
    let pick = rng() * total;
    for (const e of entries) {
        pick -= e.p;
        if (pick <= 0)
            return e.action;
    }
    return entries[entries.length - 1]?.action ?? null;
}
/** 行动家族标签（轨迹解释用）。 */
export function familyOf(action) {
    if (action.type === 'play') {
        // 家族细分在解释中不重要，统一 play 前缀。
        return `play`;
    }
    return action.type;
}
/** 对手行动生成主入口：在 state.current == actor 的合法节点调用。
 * 返回 null 表示无合法行动（理论不可达：rest 恒合法）——调用方回退 rest。 */
export function sampleOpponentAction(state, rng, ctx, omTimeAccountant) {
    if (state.phase === 'overflow') {
        const action = opponentDiscard(state);
