 * 本模块按冠军 step 的语义逐条镜像一份 SearchState 级 1-ply 转移，专用于
 * 轨迹内 1-ply 评分。正确性由 differential 测试锚定：随机状态 × 全部合法行动
 * 下，localStep 的公开后继必须与 PublicSimulation.fork().step() 逐字段一致
 * （tests/joint-sim.test.mjs）。
 *
 * 求值公式按冠军 searchGrade/routeGrade 权重逐项浅层重表达（保证"使用现有
 * 强冠军启发式进行候选排序"，任务 C.3）。本模块只服务联合搜索的轨迹内策略
 * 与根筛选，不是正式决策路径。
 */
import { GOLEM_BY_ID, MERCHANT_BY_ID } from '../data.js';
import { has } from '../engine.js';
import { initialState, actions as championActions } from '../ai/planner.js';
import { acquisitionValue, goalGap, trimStock, keepValue } from '../ai/evaluator.js';
import { weighted } from '../ai/knowledge.js';
import { engineValueFor, engineModelContext } from '../ai/engine-model.js';
import { pressureModel, golemSurvivalModel } from '../ai/opponent-model.js';
import { simViewToObservation } from './simview.js';
/** 从模拟状态构造求值上下文（每次己方/对手决策点调用；pressure 允许缓存复用）。 */
export function heuristicContext(state, params, profile, pressureCache) {
    const view = simViewToObservation(state, state.current);
    const mostClaimed = Math.max(...state.players.map(p => p.claimed.length));
    const rawStage = state.triggerPlayer !== null ? 0 : Math.max(.12, 1 - mostClaimed / (state.players.length >= 4 ? 5 : 6));
    return {
        params, profile,
        pressure: pressureCache ? pressureCache.get(state, state.current) : pressureModel(view),
        stage: Math.pow(rawStage, params.endgameWeight),
        allowAcquire: state.triggerPlayer === null,
        model: params.engineModel === 'v2' ? engineModelContext(view, params) : null,
    };
}
/** 冠军 searchGrade 公式的浅层镜像（1-ply 用；权重与 ai/planner.searchGrade 一致）。
 * futureSupport 在轨迹内省略（成本；根筛选经 screenRootActions 的目标无关项补偿）。 */
function searchGradeLite(next, preferred, ctx) {
    const goal = preferred ? GOLEM_BY_ID[preferred] : null;
    const gap = goal ? goalGap(next.stock, goal) : 0;
    return -gap * 2.6 + weighted(next.stock) * .13 * ctx.params.capacityWeight
        + engineValueFor(next, preferred, ctx.params, ctx.model ?? null) * ctx.stage * .22 * ctx.profile.engine * ctx.params.engineWeight
        + next.newCards.reduce((sum, id) => sum + acquisitionValue(next, id, preferred, ctx.profile, ctx.pressure, ctx.params, ctx.model ?? null), 0) * ctx.stage * .35
        - next.steps * .35 * ctx.profile.tempo * ctx.params.tempoWeight
        - next.acquired * .15;
}
/** 冠军 routeGrade 公式的浅层镜像（完成目标路线的单位行动得分效率）。 */
function routeGradeLite(next, preferred, ctx) {
    return next.gained * ctx.profile.tempo * ctx.params.tempoWeight / Math.pow(next.steps + .65, .90)
        + weighted(next.stock) * .055 * ctx.params.capacityWeight
        + engineValueFor(next, preferred, ctx.params, ctx.model ?? null) * ctx.stage * .085 * ctx.profile.engine * ctx.params.engineWeight;
}
/** 局部 1-ply 转移镜像（冠军 ai/planner.step 的逐条镜像；differential 锚定）。
 * 与冠军版本唯一的语义差异：不建模市场补牌（未知翻牌，冠军束搜索同样不建模）。 */
export function localStep(state, action, preferred, params) {
    if (state.terminal)
        return null;
    const next = {
        ...state, stock: [...state.stock], hand: [...state.hand], played: [...state.played],
        merchantMarket: state.merchantMarket, golemMarket: state.golemMarket,
        steps: state.steps + 1, first: state.first ?? action, path: [...state.path, action],
    };
    if (action.type === 'play') {
        const card = MERCHANT_BY_ID[action.cardId];
        if (!card)
            return null;
        const i = next.hand.indexOf(action.cardId);
        if (i < 0)
            return null;
        if (card.kind === 'create')
            card.output.forEach((n, c) => { next.stock[c] += n; });
        else if (card.kind === 'upgrade') {
            for (const c of action.steps ?? []) {
                if (!next.stock[c])
                    return null;
                next.stock[c]--;
                next.stock[c + 1]++;
            }
        }
        else {
            for (let i = 0; i < (action.repeats ?? 1); i++) {
                if (!has(next.stock, card.input))
                    return null;
                card.input.forEach((n, c) => { next.stock[c] -= n; });
                card.output.forEach((n, c) => { next.stock[c] += n; });
            }
        }
        next.hand.splice(i, 1);
        next.played.push(action.cardId);
    }
    else if (action.type === 'rest') {
        next.hand.push(...next.played);
        next.played = [];
    }
    else if (action.type === 'acquire') {
        const offer = state.merchantMarket[action.index];
        if (!offer)
            return null;
        for (const color of action.payment) {
            if (!next.stock[color])
                return null;
            next.stock[color]--;
        }
        offer.bonus.forEach((n, c) => { next.stock[c] += n; });
        next.hand.push(offer.id);
        next.newCards = [...state.newCards, offer.id];
        next.merchantMarket = state.merchantMarket.filter((_, i) => i !== action.index);
        next.acquired++;
    }
    else if (action.type === 'claim') {
        const id = state.golemMarket[action.index];
        if (!id)
            return null;
        const golem = GOLEM_BY_ID[id];
        if (!golem || !has(next.stock, golem.cost))
            return null;
        golem.cost.forEach((n, c) => { next.stock[c] -= n; });
        let coin = 0;
        if (action.index === 0) {
            if (next.copper) {
                next.copper--;
                coin = 3;
            }
            else if (next.silver) {
                next.silver--;
                coin = 1;
            }
        }
        else if (action.index === 1 && next.copper && next.silver) {
            next.silver--;
            coin = 1;
        }
        next.gained += golem.points + coin;
        next.golemMarket = state.golemMarket.filter((_, i) => i !== action.index);
        next.claimed++;
        next.terminal = next.claimed >= next.remainingClaims;
    }
    else {
        return null; // discard 在联合搜索根层由 trimStock 口径直接处理。
    }
    next.stock = trimStock(next.stock, next.golemMarket, preferred, params).stock;
    return next;
}
/** 1-ply 行动价值。认领行动走 routeGrade 语义（即时得分效率：联合搜索中
 * 每个可负担认领都是真实得分机会，与冠军"仅完成偏好目标才计 gained"的束内
 * 语义不同——束搜索的目标内嵌性不适用于根层全量行动筛选，否则会系统性屏蔽
 * 高分认领，正是任务书 §三 警告的屏蔽缺陷）。其余行动走 searchGrade。
 *
 * 休息回收激励：冠军束搜索用血统救援（restFallback）逐层保留"休息→再转换"
 * 路线席位（V4.0 修复的"休息饿死"缺陷）；贪心 1-ply 策略没有等价机制，
 * 实测会把对局打成了 23 次 acquire / 1 次 rest / 1 次 claim 的囤卡开局
 * （84 步仅得 12 分）。这里为 rest 加回收激励：已打出卡越多、手牌越空，
 * rest 的回收价值越高（restWeight 参数接入，与冠军语义一致）。 */
export function actionValue(state, action, preferred, ctx) {
    const next = localStep(state, action, preferred, ctx.params);
    if (!next)
        return -Infinity;
    if (action.type === 'claim')
        return routeGradeLite(next, preferred, ctx);
    const base = next.terminal ? routeGradeLite(next, preferred, ctx) : searchGradeLite(next, preferred, ctx);
    if (action.type === 'rest' && state.played.length > 0) {
        if (ctx.params.engineModel === 'v2' && ctx.model) {
            // AI7 C2：回收价值按"被收回卡牌的引擎价值"计，而非张数——避免
            // 为回收 1 张低价值卡而休息（审计 §4.5 的 20.3% 单卡休息）。
            const recovered = engineValueFor({ stock: state.stock, hand: [], played: state.played }, preferred, ctx.params, ctx.model);
            const relief = 0.35 * recovered + (state.hand.length === 0 ? 1.2 : 0);
            return base + relief * ctx.params.restWeight;
        }
        // 回收激励 = 已打出卡数 × restWeight；手牌为空时额外加成（无牌可打，必须回收）。
        const relief = 0.55 * state.played.length + (state.hand.length === 0 ? 1.2 : 0);
        return base + relief * ctx.params.restWeight;
    }
    return base;
}
/** 己方启发式决策（轨迹内"轮到我"时调用；state.current 必须等于 mySeat）。
 * 返回按价值降序的候选行动（首个 = 贪心选择；列表供 joint-tree 分支复用）。 */
export function myRankedActions(state, mySeat, ctx) {
    const view = simViewToObservation(state, mySeat);
    const search = initialState(view);
    // 目标偏好：市场魔像按分值潜力选优（轨迹内市场真实变化，逐决策点重选——
    // 这正是 Issue #20 修复点：市场变化后目标立即重新计算）。
    let preferred = null;
    let bestGoal = -Infinity;
    for (const id of search.golemMarket) {
        const goal = GOLEM_BY_ID[id];
        if (!goal)
            continue;
        const score = goal.points - 2.6 * goalGap(search.stock, goal);
        if (score > bestGoal) {
            bestGoal = score;
            preferred = id;
        }
    }
    const variants = championActions(search, preferred, ctx.allowAcquire, ctx.params);
    const ranked = variants
        .map(action => ({ action, value: actionValue(search, action, preferred, ctx) }))
        .filter(x => Number.isFinite(x.value))
        .sort((a, b) => b.value - a.value);
    return { search, preferred, ranked };
}
/** 根行动先验筛选分（任务 C.3：冠军启发式候选排序）。
 * claim 分两种情形（PR #26 P0-2 修复）：
 * - 立即认领（本回合即可执行）：对手没有插足机会，存活系数 = 1——绝不以
 *   "未来被抢概率"惩罚当步可完成的认领（v1 缺陷：立即认领被 golemSurvivalModel
 *   的未来存活折扣压低，S1/S5b 类盘面下高价值认领在先验中被系统性推迟）；
 * - 未来目标规划（非 claim 行动）：按 0.6 + 0.4×survival 弱折扣保持路线相关性，
 *   把"目标可能被截胡"的风险计入长线 acquire/转配决策。
 *
 * options.goalScope（PR #26 修复性能项）：'all'（缺省，v1 语义：逐行动 × 全部目标
 * 取最好值——JS2-4 根筛选口径）| 'preferred'（只对 [null, preferredGoal] 打分——
 * JS5 根筛选口径：3-5 人中局全量合法集 ~300-500 行动 × 全目标打分实测 70-90ms，
 * 会把预算耗尽在试验开始前；冠军引导场景下偏好目标已知，收窄到 2 目标后 ~10ms）。 */
export function screenRootActions(view, rootActions, ctx, survival, options) {
    const search = initialState(view);
    // 立即认领判定：观察者是当前行动者且库存足额（合法枚举保证 claim 均可支付）。
    const iAmCurrent = view.current === view.playerId;
    const myStock = iAmCurrent ? view.players[view.playerId].stock : null;
    const goalScope = options?.goalScope ?? 'all';
    const preferredGoal = options?.preferredGoal ?? null;
    // 根筛选逐行动对其最相关目标取最好值。
    const scored = rootActions.map(action => {
        let best = -Infinity;
        const goals = action.type === 'claim'
            ? [view.golemMarket[action.index]]
            : goalScope === 'preferred'
                ? (preferredGoal ? [null, preferredGoal] : [null])
                : [null, ...view.golemMarket];
        for (const preferred of goals) {
            const value = actionValue(search, action, preferred, ctx);
            if (!Number.isFinite(value))
                continue;
            let adjusted = value;
            if (action.type === 'claim' && preferred) {
                const immediate = !!myStock && payableClaim(myStock, preferred);
                adjusted *= immediate ? 1 : (survival[preferred] ?? 1);
            }
            else if (preferred) {
                adjusted *= 0.6 + 0.4 * (survival[preferred] ?? 1);
            }
            if (adjusted > best)
                best = adjusted;
        }
        return { action, prior: Number.isFinite(best) ? best : -Infinity };
    });
    return scored.sort((a, b) => b.prior - a.prior);
}
/** 根目标存活表（冠军 golemSurvivalModel 包装：公开信息，成本 O(玩家×市场)）。 */
export function rootSurvival(view, depthRounds) {
    return golemSurvivalModel(view, depthRounds >= 2 ? 6 : depthRounds === 1 ? 3 : 1);
}
/** 溢出弃置决策（冠军 trimStock 同一口径；overflow 阶段唯一合法行动族）。 */
export function discardDecision(stock, golemMarket, params) {
    return trimStock([...stock], golemMarket, null, params).discarded;
}
/** 1-ply 局部镜像与模拟器转移的一致性检查入口（differential 测试用）：
 * 给定 SearchState 与行动，返回局部镜像的公开后继摘要；测试侧与
 * PublicSimulation.fork().step() 的结果逐字段比对。 */
export function localSuccessorSummary(state, action, preferred, params) {
    const next = localStep(state, action, preferred, params);
    if (!next)
        return null;
    return {
        stock: next.stock.join(','),
        hand: [...next.hand].sort().join(','),
        played: [...next.played].sort().join(','),
        merchant: next.merchantMarket.map((m) => `${m.id}:${m.bonus.join(',')}`).join(';'),
        golem: next.golemMarket.join(','),
        gained: next.gained,
    };
}
/** 支付候选（keepValue top-K；冠军 payments 口径的显式复用入口）。
 * K=3 与冠军一致；根层全量合法集不受此影响（根层用 enumerateLegalActions）。 */
export function topPayments(stock, index, goals, preferred, params, k = 3) {
    if (index === 0)
        return [[]];
    const result = [];
    function walk(color, left, selected, rest) {
        if (color === 4) {
            if (left === 0)
                result.push({ payment: selected, value: keepValue(rest, goals, preferred, params) });
            return;
        }
        for (let n = 0; n <= Math.min(stock[color], left); n++) {
            const next = [...rest];
            next[color] -= n;
            walk(color + 1, left - n, [...selected, ...Array(n).fill(color)], next);
        }
    }
    walk(0, index, [], [...stock]);
    result.sort((a, b) => b.value - a.value || a.payment.join('').localeCompare(b.payment.join('')));
    return result.slice(0, k).map(x => x.payment);
}
/** 检查魔像是否可支付（防御性）。 */
export function payableClaim(stock, golemId) {
    const goal = GOLEM_BY_ID[golemId];
    return !!goal && has([...stock], goal.cost);
}

/** 模拟状态视图工具：PublicSimState → 冠军求值函数所需的轻量视图。
 *
 * 冠军求值器（ai/evaluator、ai/knowledge、ai/opponent-model）的入参是
 * AIObservation 或其子字段。联合搜索在模拟轨迹内复用这些已验证公式，
 * 需要把 PublicSimState 映射为结构兼容的只读视图。映射是纯字段投影，
 * 不引入任何隐藏信息（PublicSimState 本身只含公开可推导内容）。
 */
import { GOLEM_BY_ID, MERCHANT_BY_ID } from '../data.js';
import { has } from '../engine.js';
import { NEUTRAL_PROFILE, PROFILES } from '../ai/profiles.js';
import { pressureModel } from '../ai/opponent-model.js';
/** PublicSimState 玩家 → ObservationPlayer 结构投影（同一字段子集）。 */
function playerView(p) {
    return {
        id: p.id,
        name: p.name,
        isAI: p.isAI,
        stock: [...p.stock],
        hand: [...p.hand],
        played: [...p.played],
        claimed: [...p.claimed],
        copper: p.copper,
        silver: p.silver,
        turns: p.turns,
    };
}
/** PublicSimState → AIObservation 结构兼容视图（字段投影；viewer 指定观察席位）。
 * 仅用于调用冠军求值公式；不参与正式决策路径。 */
export function simViewToObservation(state, viewer) {
    return {
        playerId: viewer,
        players: state.players.map(playerView),
        current: state.current,
        merchantMarket: state.merchantMarket.map(m => ({ id: m.id, bonus: [...m.bonus] })),
        golemMarket: [...state.golemMarket],
        copper: state.copper,
        silver: state.silver,
        phase: state.phase,
        triggerPlayer: state.triggerPlayer,
        turnNumber: state.turnNumber,
    };
}
/** 按显式人格名解析（NEUTRAL_PROFILE / PROFILES 名称匹配）；未知名回落中立。
 * 与训练模拟器 seatProfile 的显式注入语义一致：人格只影响求值乘子。 */
export function profileByName(name) {
    if (!name)
        return NEUTRAL_PROFILE;
    if (name === NEUTRAL_PROFILE.name)
        return NEUTRAL_PROFILE;
    return PROFILES.find(p => p.name === name) ?? NEUTRAL_PROFILE;
}
/** 决策者人格的席位推导（与正式游戏 profileFor 语义一致，供缺省路径使用）。 */
export function profileForSeat(view) {
    const aiIndex = view.players.slice(0, view.current + 1).filter(p => p.isAI).length - 1;
    return PROFILES[Math.max(0, aiIndex) % PROFILES.length] ?? NEUTRAL_PROFILE;
}
/** 玩家单圈可达水晶：当前库存 + 打出全部手牌的净产出（与
 * ai/opponent-model.reachableStock 同口径的紧凑实现，供 L2 竞争项使用）。 */
export function reachableStockOf(stock, hand) {
    const out = [...stock];
    for (const id of hand) {
        // 卡牌表查询内联（避免循环依赖 data 模块逐卡判断）。
        const card = MERCHANT_BY_ID[id];
        if (!card)
            continue;
        if (card.kind === 'create') {
            card.output.forEach((n, c) => { out[c] += n; });
        }
        else if (card.kind === 'upgrade') {
            let steps = card.steps;
            for (let c = 0; c < 3 && steps > 0; c++) {
                while (steps > 0 && out[c] > 0) {
                    out[c]--;
                    out[c + 1]++;
                    steps--;
                }
            }
        }
        else if (card.kind === 'trade' && has(out, card.input)) {
            card.input.forEach((n, c) => { out[c] -= n; });
            card.output.forEach((n, c) => { out[c] += n; });
        }
    }
    return out;
}
/** 轨迹内压力模型缓存：同一模拟状态键只计算一次（任务 E：状态相关缓存）。
 * 压力模型输入是市场 + 全体玩家引擎，随市场变化必须失效——以
 * turnNumber + current + 市场 id 序列 + current 玩家手牌数为键的近似失效
 * 在轨迹内足够安全（键碰撞只会命中同一局面的等价缓存）。 */
export class PressureCache {
    cache = new Map();
    get(state, viewer) {
        const key = `${state.turnNumber}|${state.current}|${state.merchantMarket.map(m => `${m.id}:${m.bonus.join(',')}`).join(';')}|${state.players.map(p => p.hand.length + p.played.length).join(',')}`;
        const hit = this.cache.get(key);
        if (hit)
            return hit;
        const model = pressureModel(simViewToObservation(state, viewer));
        this.cache.set(key, model);
        return model;
    }
}
/** 当前决策者的目标偏好：市场魔像按（分值潜力 − 费用缺口）选最优，
 * 供轨迹内己方启发式与根筛选共用。 */
export function preferredGoalOf(stock, golemMarket, gapOf) {
    let best = null;
    let bestScore = -Infinity;
    for (const id of golemMarket) {
        const goal = GOLEM_BY_ID[id];
        if (!goal)
            continue;
        const score = goal.points - 2.6 * gapOf(stock, id);
        if (score > bestScore) {
            bestScore = score;
            best = id;
        }
    }
    return best;
}

/** Joint Search V1 共享类型（AI6 第四阶段·任务 A）。
 *
 * 模块定位：src/js/ 是独立的多玩家联合规划器实验模块。与 src/ai（正式冠军）
 * 完全隔离：正式网页 AI 决策路径不 import 本模块，冠军行为逐位不变；
 * 本模块经独立实验适配器（./adapter.ts）按显式版本注入训练评测。
 *
 * 信息边界（不可妥协，与 src/sim、src/om 同一纪律）：
 * - 规划输入只允许 AIObservation 公开观察 + 公开历史摘要 + 显式版本化参数；
 * - 模拟随机流独立于正式游戏 RNG（PublicSimulation 信念采样 + 显式种子）；
 * - 不访问隐藏牌库顺序（结构上不可达，见 tests/joint-fairness.test.mjs 静态扫描）。
 *
 * Issue #20 根本缺陷的修复定位（任务书 §一）：
 * 旧 Beam Search 推演序列是"我→我→我→我"，对手行动与市场补牌从未真实进入
 * 自身行动之间的时序。Joint Search 的推演序列是"我→下家→其余玩家按座位→
 * 我→……→终局/叶子"，全部经 PublicBeliefSimulator 精确推进（任务 B）。
 */
