/** ClaimETAModel：魔像认领时间预测（AI6 第三阶段·任务 D）。
 *
 * 输出（对每名对手 j、每张公开魔像 g）：
 * - P(对手 j 在未来第 k 次自身行动时认领 g)——按自身行动序数的概率分布；
 * - 最早规则可达时间（贪心直线规划，独立于概率分布——两者严格区分）；
 * - 指定窗口内的累计认领概率与窗口外质量（未认领/被抢/终局）。
 *
 * 估计方式：固定策略的浅层概率 rollout（OpponentPolicyV1 驱动全部席位，
 * 信念采样未来翻牌，按真实行动顺序推进）。不假设对手以最短路径行动，
 * 不实现完整 Joint MCTS（任务书约束）。
 *
 * 删失与竞争事件的正确处理：目标被他人抢走、游戏结束、窗口内未认领
 * 三类结果显式分离（pStolenBefore / pGameEnded / pBeyond），绝不在
 * "成功认领样本"子集上单独计算误差口径。
 */
import { featurePack } from './features.js';
import { greedyBeelineEstimate, runRaceRollouts } from './rollout.js';
/** 认领 ETA 预测主入口。 */
export function predictClaimETA(ctx, playerId, golemId, horizon, batch, deadline) {
    const { state } = ctx;
    const notes = [];
    const H = Math.max(1, Math.floor(horizon));
    const pClaimAt = new Array(H).fill(0);
    if (!state.golemMarket.includes(golemId)) {
        notes.push('目标魔像已不在公开市场（已被认领/不存在）：全部质量归入窗口外');
        return zeroETA(ctx, playerId, golemId, H, 'golem-not-in-market', notes);
    }
    if (state.phase === 'finished') {
        notes.push('对局已结束');
        return zeroETA(ctx, playerId, golemId, H, 'finished', notes);
    }
    const records = (batch ?? runRaceRollouts(state, ctx.history, golemId, ctx, ctx.config.rollouts, deadline)).records;
    const samples = records.length || 1;
    let stolen = 0;
    let ended = 0;
    for (const rec of records) {
        const claim = rec.claims.find(c => c.playerId === playerId);
        if (claim) {
            // 本人在 k≤H 认领 → 计入分布；k>H → 落入 pBeyond（本人认领但晚于窗口）。
            if (claim.k <= H)
                pClaimAt[claim.k - 1] += 1;
        }
        else if (rec.claims.length > 0) {
            stolen += 1;
        }
        else if (rec.finished) {
            ended += 1;
        }
    }
    const cumulative = [];
    let acc = 0;
    for (let k = 0; k < H; k++) {
        acc += pClaimAt[k];
        cumulative.push(acc / samples);
    }
    for (let k = 0; k < H; k++)
        pClaimAt[k] /= samples;
    const pStolenBefore = stolen / samples;
    const pGameEnded = ended / samples;
    const pBeyond = Math.max(0, 1 - cumulative[H - 1]);
    // 最早规则可达时间（贪心直线规划，与概率分布严格分离）。
    const beeline = greedyBeelineEstimate(state, ctx.history, playerId, golemId, ctx);
    if (beeline.k !== null && beeline.k > H) {
        notes.push(`贪心可达时间 k=${beeline.k} 超出预测窗口 ${H}`);
    }
    return {
        playerId, golemId, horizon: H,
        earliestRuleEstimate: beeline.k,
        earliestRuleBlockedBy: beeline.blockedBy,
        pClaimAt, cumulative, pBeyond,
        pStolenBefore, pGameEnded,
        samples: records.length,
        notes,
    };
}
function zeroETA(ctx, playerId, golemId, horizon, reason, notes) {
    void ctx;
    return {
        playerId, golemId, horizon,
        earliestRuleEstimate: null,
        earliestRuleBlockedBy: reason === 'finished' ? 'ended' : 'stolen',
        pClaimAt: new Array(horizon).fill(0),
        cumulative: new Array(horizon).fill(0),
        pBeyond: 1, pStolenBefore: 0, pGameEnded: 0,
        samples: 0,
        notes: [...notes, `reason:${reason}`],
    };
}
/** 批量便捷入口：全部对手 × 全部公开魔像（Joint Search 消费形态）。 */
export function predictAllClaimETAs(ctx, horizon, deadline) {
    const { state, config } = ctx;
    const pack = featurePack(state);
    void pack;
    const H = horizon ?? config.etaHorizon;
    const out = [];
    for (const golemId of state.golemMarket) {
        const batch = runRaceRollouts(state, ctx.history, golemId, ctx, config.rollouts, deadline);
        for (const p of state.players) {
            if (p.id === state.current)
                continue; // 对手口径；当前席位由决策器自评
            out.push(predictClaimETA(ctx, p.id, golemId, H, batch, deadline));
        }
    }
    return out;
}

/** Opponent Model V1 共享特征（AI6 第三阶段）。
 *
 * 全部特征只消费 PublicSimState / PublicHistorySummary / 公开卡表，
 * 不接触隐藏牌序，不使用真实游戏 RNG。
 * 部分特征与 ai/knowledge.ts、ai/opponent-model.ts 同源（水晶价值标尺、
 * 单圈可达库存的贪心口径），便于 M0–M4 对照在同一特征语言下比较；
 * 但 V1 的概率模型本身不把旧启发式公式当作已验证的真实概率（任务书约束）。
 */
import { count, has } from '../engine.js';
import { GOLEM_BY_ID, MERCHANT_BY_ID } from '../data.js';
import { VALUES, weighted, stockCount } from '../ai/knowledge.js';
/** 风格先验（工程假设：balanced 为主锚，其余均分）。 */
export const STYLE_PRIOR = {
    rush: 0.1375, engine: 0.1375, coin: 0.1375, contest: 0.1375, balanced: 0.45,
};
/** 终局认领门槛（2–3 人 6 张、4–5 人 5 张；与 engine/transition 镜像）。 */
export function endgameThreshold(playerCount) {
    return playerCount >= 4 ? 5 : 6;
}
/** 单圈可达库存：当前库存 + 打出全部手牌的净产出（贪心确定性模拟），
 * 超过商队上限 10 按价值最低色逐颗弃置（与 ai/opponent-model.ts reachableStock 同口径）。
 * restReactivate：同时叠加"休息收回已打出卡再打一轮"的引擎产出（上限近似）。 */
export function reachableStock(p, options) {
    const stock = [...p.stock];
    const handOutput = productionOfHand(p.hand, stock);
    for (let c = 0; c < 4; c++)
        stock[c] += handOutput[c];
    if (options?.includeRest) {
        const engineOutput = productionOfPlayed(p.played, stock);
        for (let c = 0; c < 4; c++)
            stock[c] += engineOutput[c];
    }
    // 商队上限 10：超出按价值最低色逐颗弃置（确定性近似）。
    while (stockCount(stock) > 10) {
        let color = -1;
        for (let c = 0; c < 4; c++) {
            if (stock[c] === 0)
                continue;
            if (color < 0 || VALUES[c] < VALUES[color])
                color = c;
        }
        if (color < 0)
            break;
        stock[color]--;
    }
    return stock;
}
/** 打出全部手牌一次的净产出（贪心：创造→交易按净增值→升级贪心低转高）。 */
export function productionOfHand(hand, stock) {
    const s = [...stock];
    for (const id of hand) {
        const card = MERCHANT_BY_ID[id];
        if (!card)
            continue;
        if (card.kind === 'create') {
            card.output.forEach((n, c) => { s[c] += n; });
        }
        else if (card.kind === 'trade' && has(s, card.input)) {
            card.input.forEach((n, c) => { s[c] -= n; });
            card.output.forEach((n, c) => { s[c] += n; });
        }
        // 升级卡的产出依赖执行顺序，贪心放到最后统一处理。
    }
    // 升级卡贪心：低色充足时逐卡逐步低转高。
    for (const id of hand) {
        const card = MERCHANT_BY_ID[id];
        if (!card || card.kind !== 'upgrade')
            continue;
        let steps = card.steps;
        for (let c = 0; c < 3 && steps > 0; c++) {
            while (steps > 0 && s[c] > 0) {
                s[c]--;
                s[c + 1]++;
                steps--;
            }
        }
    }
    const delta = s.map((v, c) => v - stock[c]);
    return delta;
}
/** 已打出引擎（休息后可再打一轮）的单圈产出。 */
export function productionOfPlayed(played, stock) {
    return productionOfHand(played, stock);
}
/** 费用覆盖度 [0,1]：加权 min(有, 需) / 加权费用。 */
export function coverageOf(cost, have) {
    const total = weighted(cost);
    if (total <= 0)
        return 1;
    const covered = cost.reduce((s, n, c) => s + Math.min(n, have[c]) * VALUES[c], 0);
    return Math.min(1, covered / total);
}
/** 费用缺口。 */
export function gapOf(cost, have) {
    return cost.map((n, c) => Math.max(0, n - have[c]));
}
/** 乐观可达轮数估计：缺口按每轮生产补齐（向上取整，逐色独立乐观口径）。 */
export function turnsToAfford(gap, production) {
    let rounds = 0;
    for (let c = 0; c < 4; c++) {
        if (gap[c] <= 0)
            continue;
        const per = Math.max(0, production[c]);
        rounds = Math.max(rounds, per > 0 ? Math.ceil(gap[c] / per) : 99);
    }
    return rounds;
}
/** 认领位置硬币奖励的期望分值（0 号位铜→银回退；1 号位铜银双全给银）。 */
export function coinValueOf(index, pools) {
    if (index === 0)
        return pools.copper > 0 ? 3 : pools.silver > 0 ? 1 : 0;
    if (index === 1)
        return pools.copper > 0 && pools.silver > 0 ? 1 : 0;
    return 0;
}
export function playerFeatures(p, threshold) {
    const handProduction = productionOfHand(p.hand, p.stock);
    const engineProduction = productionOfPlayed(p.played, p.stock);
    const reachable = reachableStock(p, { includeRest: true });
    const score = p.claimed.reduce((s, id) => s + (GOLEM_BY_ID[id]?.points ?? 0), 0)
        + p.copper * 3 + p.silver
        + p.stock.slice(1).reduce((s, x) => s + x, 0);
    return {
        id: p.id,
        stock: [...p.stock],
        hand: [...p.hand],
        played: [...p.played],
        claimed: [...p.claimed],
        copper: p.copper,
        silver: p.silver,
        turns: p.turns,
        handCount: p.hand.length,
        playedCount: p.played.length,
        score,
        golemsToGo: Math.max(0, threshold - p.claimed.length),
        reachable,
        handProduction,
        engineProduction,
    };
}
export function featurePack(state) {
    const threshold = endgameThreshold(state.playerCount);
    const players = state.players.map(p => playerFeatures(p, threshold));
    const byId = new Map(players.map(p => [p.id, p]));
    return {
        state,
        threshold,
        players,
        byId,
        rivalsAhead(viewerId) {
            return state.players
                .map(p => p.id)
                .filter(id => id !== viewerId && aheadInSeatOrder(viewerId, id, state.current, state.playerCount));
        },
    };
}
/** 座位顺序：从 current 开始轮转，a 是否先于 b 行动。 */
export function aheadInSeatOrder(a, b, current, n) {
    const da = (a - current + n) % n;
    const db = (b - current + n) % n;
    return da < db;
}
// === 状态适配器 ===
/** PublicSimState → AIObservation 兼容对象（只读投影；不冻结、不外泄隐藏信息——
 * 状态本身只含公开信息）。用于复用 ai/knowledge / ai/opponent-model 的公开特征函数
 * （M1 对照口径），以及 createSimulation 的入口参数。 */
export function stateToObservation(state, viewerId = state.current) {
    const players = state.players.map(p => ({
        id: p.id,
        name: p.name,
        isAI: p.isAI,
        stock: [...p.stock],
        hand: [...p.hand],
        played: [...p.played],
        claimed: [...p.claimed],
        copper: p.copper,
        silver: p.silver,
        turns: p.turns,
    }));
    return {
        playerId: viewerId,
        players,
        current: state.current,
        merchantMarket: state.merchantMarket.map(m => ({ id: m.id, bonus: [...m.bonus] })),
        golemMarket: [...state.golemMarket],
        copper: state.copper,
        silver: state.silver,
        phase: state.phase,
        triggerPlayer: state.triggerPlayer,
        turnNumber: state.turnNumber,
    };
}
/** PublicSimState 深拷贝（预测内假设分支用；字段与 state.ts 布局一致）。 */
export function cloneState(state) {
    return {
        playerCount: state.playerCount,
        players: state.players.map(p => ({
            ...p,
            stock: [...p.stock],
            hand: [...p.hand],
            played: [...p.played],
            claimed: [...p.claimed],
        })),
        current: state.current,
        merchantMarket: state.merchantMarket.map(m => ({ id: m.id, bonus: [...m.bonus] })),
        golemMarket: [...state.golemMarket],
        copper: state.copper,
        silver: state.silver,
        phase: state.phase,
        triggerPlayer: state.triggerPlayer,
        turnNumber: state.turnNumber,
        unseenMerchants: [...state.unseenMerchants],
        unseenGolems: [...state.unseenGolems],
        historySummary: structuredClone(state.historySummary),
    };
}
/** 行动族归类（策略与解释共用）。 */
export function familyOf(action) {
    switch (action.type) {
        case 'claim': return 'claim';
        case 'acquire': return 'acquire';
        case 'rest': return 'rest';
        case 'discard': return 'discard';
        case 'play': {
            const card = MERCHANT_BY_ID[action.cardId];
            if (card?.kind === 'create')
                return 'produce';
            if (card?.kind === 'upgrade')
                return 'upgrade';
            return 'trade';
        }
    }
}
/** 魔像目标被多少对手"接近"（竞争度 [0,1]）：全体对手覆盖度的 softmax-ish 聚合。 */
export function contestedOf(cost, rivals) {
    if (!rivals.length)
        return 0;
    const coverages = rivals.map(r => coverageOf(cost, r.reachable));
    return Math.min(1, Math.max(...coverages));
}
/** 玩家手牌+引擎对费用的产出契合度 [0,1]：产出与缺口的加权交集 / 缺口。 */
export function engineAffinityOf(cost, feats) {
    const gap = gapOf(cost, feats.reachable);
    const gapTotal = weighted(gap);
    if (gapTotal <= 0)
        return 1;
    const supply = feats.handProduction.map((n, c) => n + feats.engineProduction[c] * 0.5);
    const useful = gap.reduce((s, n, c) => s + Math.min(n, Math.max(0, supply[c])) * VALUES[c], 0);
    return Math.min(1, useful / gapTotal);
}
// === 数值工具 ===
/** 数值安全化：非有限值归零（概率约束防线的最后兜底）。 */
export function safeNumber(v, fallback = 0) {
    return Number.isFinite(v) ? v : fallback;
}
/** softmax（带温度；输入 logits；输出与输入等长、Σ=1、全部 > 0）。 */
export function softmax(logits, temperature) {
    const t = temperature > 1e-9 ? temperature : 1e-9;
    const max = Math.max(...logits.map(l => safeNumber(l, -1e9)));
    const exps = logits.map(l => Math.exp((safeNumber(l, -1e9) - max) / t));
    const sum = exps.reduce((s, e) => s + e, 0) || 1;
    return exps.map(e => e / sum);
}
/** 归一化（Σ=1；全零输入均匀分布）。 */
export function normalize(values) {
    const sum = values.reduce((s, v) => s + Math.max(0, v), 0);
    if (sum <= 0 || !Number.isFinite(sum))
        return values.map(() => 1 / values.length);
    return values.map(v => Math.max(0, v) / sum);
}
/** 席位数（防御性约束；正式游戏 2–6）。 */
export function clampSeat(x, n) {
    return Math.min(n - 1, Math.max(0, Math.floor(x)));
}
export { count, VALUES, weighted, stockCount, has };

/** OpponentModel：对手行为与竞争风险预测的统一接口（AI6 第三阶段·任务 F）。
 *
 * 为 Joint Search V1 提供结构化概率输出：
 * - predictAction    下一步行动分布（任务 B）
 * - predictIntent    战略意图分布（任务 C）
 * - predictClaimETA  认领时间分布（任务 D）
 * - predictSurvival  目标存活概率（任务 E）
 *
 * 工程约束：
 * - 完全本地离线；Node 与浏览器通用（纯 TS，无 DOM/Node API）；
 * - 不依赖 LLM API；不暴露隐藏牌序；不使用真实游戏 RNG；
 * - 相同公开状态 + 相同预测种子 ⇒ 逐位可复现（种子显式传入）；
 * - 按状态键 + 历史摘要指纹的 LRU 预测缓存；明确的预测时间预算；
 * - 输出携带解释字段（explain / notes / styleEvidence / samples）；
 * - 现有冠军默认不调用本模块（正式对局行为不变）。
 *
 * M0–M4 评测口径（经 OpponentModelOptions 配置）：
 * - M0：无历史规则先验（useHistory=false, useHistoryStyle=false）；
 * - M2：规则式行动与 ETA（rollout 驱动，无历史特征）；
