import { createSimulation, enumerateLegalActions, hashPublicState, mulberry32, } from '../sim/index.js';
import { GOLEM_BY_ID, MERCHANT_BY_ID } from '../data.js';
import { VALUES } from '../ai/knowledge.js';
import { featurePack, stateToObservation, STYLE_PRIOR } from './features.js';
import { predictIntent } from './intent.js';
import { predictActionDistribution, sampleAction } from './policy.js';
/** 确定性种子混合（FNV-1a 32 位）。 */
export function mixSeed(...parts) {
    let h = 0x811c9dc5;
    const feed = (s) => {
        for (let i = 0; i < s.length; i++) {
            h ^= s.charCodeAt(i);
            h = Math.imul(h, 0x01000193);
        }
    };
    for (const p of parts)
        feed(String(p));
    return h >>> 0;
}
const MAX_ROLLOUT_STEPS = 200;
/** 运行一批竞争 rollout（任务 D/E 共享）。 */
export function runRaceRollouts(state, history, golemId, ctx, count, deadline) {
    const n = state.playerCount;
    // root 一次计算风格与意图（静态近似：rollout 内意图不随状态漂移重估）。
    const pack = featurePack(state);
    const styles = new Map();
    for (const p of state.players) {
        const intent = predictIntent({ state, history, config: ctx.config }, p.id, pack);
        styles.set(p.id, intent.style);
    }
    const stateKey = String(hashPublicState(state));
    const records = [];
    for (let r = 0; r < count; r++) {
        if (deadline !== undefined && performance.now() > deadline)
            break;
        const simSeed = mixSeed('race', stateKey, golemId, ctx.config.seed, r);
        const sim = createSimulation(stateToObservation(state), { simSeed, historySummary: history });
        const presence = Array.from({ length: n }, () => []);
        const claims = [];
        const own = new Array(n).fill(0);
        const rng = mulberry32(simSeed ^ 0x9e3779b9);
        let steps = 0;
        let claimedBy = -1;
        while (!sim.finished && steps < MAX_ROLLOUT_STEPS) {
            const view = sim.view;
            const actor = view.current;
            // 记录该行动者本自身行动时点的目标在场性（决策点语义：行动前时刻）。
            presence[actor].push(view.golemMarket.includes(golemId));
            own[actor] += 1;
            const legal = enumerateLegalActions(view, { dedupe: true });
            if (!legal.length)
                break;
            const dist = predictActionDistribution({
                state: view,
                history: view.historySummary,
                temperature: ctx.config.temperature,
                style: styles.get(actor) ?? STYLE_PRIOR,
                pack: featurePack(view),
            });
            const picked = sampleAction(dist, rng());
            if (!picked)
                break;
            // 认领目标即记录并停止后续（同一魔像不可被二次认领）。
            if (picked.action.type === 'claim' && view.golemMarket[picked.action.index] === golemId) {
                claims.push({ playerId: actor, k: own[actor] });
                claimedBy = actor;
            }
            sim.step(picked.action);
            steps += 1;
            // 目标已被认领后：ETA 窗口已解决；Survival 需要的后续在场性恒为 false，
            // 继续模拟到各席位越过预测窗口即提前截断（性能保护，不改变语义）。
            if (claimedBy >= 0 && Math.min(...own) >= Math.max(ctx.config.horizon, ctx.config.etaHorizon))
                break;
        }
        records.push({ claims, presence, finished: sim.finished, steps });
    }
    return { records, styles };
}
// === 最早规则可达时间（贪心直线规划；与概率分布严格分离） ===
const BEELINE_CAP = 8;
/** 贪心直线估计：目标玩家每自身行动都朝目标魔像推进（可认领立即认领），
 * 其余玩家按策略 Top-1 行动。返回达成认领所需的自身行动序数（1 起始）。
 * 这是一条合法可实现路径的长度估计（可达时间的诚实近似，非数学下界）；
 * 被抢/终局/超过 BEELINE_CAP 未达成时返回 null 并说明原因。 */
export function greedyBeelineEstimate(state, history, playerId, golemId, ctx) {
    if (!state.golemMarket.includes(golemId))
        return { k: null, blockedBy: 'stolen' };
    if (state.phase === 'finished')
        return { k: null, blockedBy: 'ended' };
    const stateKey = String(hashPublicState(state));
    const simSeed = mixSeed('beeline', stateKey, golemId, ctx.config.seed);
    const sim = createSimulation(stateToObservation(state), { simSeed, historySummary: history });
    let own = 0;
    let steps = 0;
    while (!sim.finished && steps < MAX_ROLLOUT_STEPS) {
        const view = sim.view;
        const actor = view.current;
        if (!view.golemMarket.includes(golemId))
            return { k: null, blockedBy: 'stolen' };
        const legal = enumerateLegalActions(view, { dedupe: true });
        if (!legal.length)
            break;
        let action = legal[0];
        if (actor === playerId) {
            own += 1;
            const claimNow = legal.find(a => a.type === 'claim' && view.golemMarket[a.index] === golemId);
            if (claimNow)
                return { k: own, blockedBy: null };
            if (own >= BEELINE_CAP)
                return { k: null, blockedBy: 'unreachable' };
            action = beelineAction(view, legal, playerId, golemId);
        }
        else {
            const pack = featurePack(view);
            const dist = predictActionDistribution({
                state: view, history: view.historySummary, temperature: ctx.config.temperature,
                style: STYLE_PRIOR, pack,
            });
            const best = dist.entries.reduce((b, e) => (e.p > b.p ? e : b), dist.entries[0] ?? null);
            if (!best)
                break;
            action = best.action;
        }
        sim.step(action);
        steps += 1;
    }
    return { k: null, blockedBy: sim.finished ? 'ended' : 'unreachable' };
}
/** 直线行动选择：使目标魔像费用覆盖度增长最大的合法行动（平局按族优先）。 */
function beelineAction(view, legal, playerId, golemId) {
    const goal = GOLEM_BY_ID[golemId];
    if (!goal)
        return legal[0];
    const pack = featurePack(view);
    const feats = pack.byId.get(playerId);
    let best = legal[0];
    let bestGain = -1e9;
    const familyRank = { claim: 0, produce: 1, trade: 2, upgrade: 3, acquire: 4, rest: 5, discard: 6 };
    for (const a of legal) {
        if (a.type === 'discard')
            continue;
        // 一步后可达库存的确定性近似（打出/获取/休息的即时产出）。
        let gain = -1e9;
        if (a.type === 'rest') {
            const engineGain = feats.engineProduction.reduce((s, n, c) => s + Math.min(Math.max(0, goal.cost[c] - feats.stock[c]), Math.max(0, n)) * VALUES[c], 0);
            gain = feats.playedCount > 0 ? engineGain : -1e8;
        }
        else if (a.type === 'play') {
            const card = MERCHANT_BY_ID[a.cardId];
            if (!card)
                continue;
            const delta = card.kind === 'create'
                ? card.output
                : card.kind === 'trade'
                    ? tradeDelta(card.input, card.output, a.repeats ?? 1)
                    : upgradeDelta(a.steps ?? []);
            gain = deltaGain(delta, goal.cost, feats.stock);
        }
        else if (a.type === 'acquire') {
            const slot = view.merchantMarket[a.index];
            const card = slot ? MERCHANT_BY_ID[slot.id] : null;
            if (!card)
                continue;
            const paymentCost = a.payment.length;
            const bonus = slot ? slot.bonus : [0, 0, 0, 0];
            const delta = [0, 1, 2, 3].map(c => (card.output?.[c] ?? 0) + (bonus[c] ?? 0));
            gain = deltaGain(delta, goal.cost, feats.stock) - paymentCost * 0.12;
        }
        gain -= (familyRank[a.type === 'play' ? familyOfPlay(a.cardId) : a.type] ?? 9) * 1e-6;
        if (gain > bestGain) {
            bestGain = gain;
            best = a;
        }
    }
    return best;
}
function familyOfPlay(cardId) {
    const card = MERCHANT_BY_ID[cardId];
    if (card?.kind === 'create')
        return 'produce';
    if (card?.kind === 'upgrade')
        return 'upgrade';
    return 'trade';
}
function tradeDelta(input, output, repeats) {
    return [0, 1, 2, 3].map(c => (output[c] - input[c]) * repeats);
}
function upgradeDelta(steps) {
    const delta = [0, 0, 0, 0];
    for (const s of steps) {
        delta[s] -= 1;
        delta[s + 1] += 1;
    }
    return delta;
}
function deltaGain(delta, cost, stock) {
    return delta.reduce((s, d, c) => s + Math.min(Math.max(0, cost[c] - stock[c]), Math.max(0, d)) * VALUES[c], 0);
}

/** TargetSurvivalModel：公开魔像目标存活概率与截胡风险（AI6 第三阶段·任务 E）。
 *
 * 输出：对当前公开魔像 g 与观察席位 v 的未来决策点 τ_k（v 的第 k 次自身行动），
 * 估计 P(g 在 τ_k 时仍位于公开市场)。
 *
 * 估计方式：与 ClaimETA 共享同一批按座位顺序推进的规则式随机 rollout。
 * 公共目标被唯一认领、先抢走者改变其余玩家的后续行为（目标重定向）、
 * 终局提前结束——全部由同一模拟轨迹内生地处理，绝不把各对手的独立
 * 抢牌概率相乘后冒充真实存活概率（任务书 E 纪律）。
 *
 * 与既有 golemSurvivalModel（M1，座位感知启发式公式）的关系：
 * 本模型是独立实现，二者在评测系统中做对照（Brier/ECE 校准比较）。
 */
import { runRaceRollouts } from './rollout.js';
/** 目标存活预测主入口。 */
export function predictSurvival(ctx, golemId, horizon, viewerId, batch, deadline) {
    const { state } = ctx;
    const viewer = viewerId ?? state.current;
    const notes = [];
    const H = Math.max(0, Math.floor(horizon));
    const pPresentAt = new Array(H + 1).fill(0);
    const reachRate = new Array(H + 1).fill(0);
    if (!state.golemMarket.includes(golemId)) {
        notes.push('目标魔像已不在公开市场');
        return {
            golemId, viewerId: viewer, horizon: H,
            pPresentAt: new Array(H + 1).fill(0),
            reachRate: new Array(H + 1).fill(0),
            jointReachPresent: new Array(H + 1).fill(0),
            perRival: state.players.filter(p => p.id !== viewer).map(p => ({ playerId: p.id, pClaimWithin: 0 })),
            samples: 0, notes,
        };
    }
    // k=0：当前时刻（决定性：魔像在场即为 1，不经 rollout）。
    pPresentAt[0] = 1;
    reachRate[0] = 1;
    if (state.phase === 'finished') {
        notes.push('对局已结束：未来决策点不存在');
        for (let k = 1; k <= H; k++) {
            pPresentAt[k] = 0;
            reachRate[k] = 0;
        }
        return {
            golemId, viewerId: viewer, horizon: H, pPresentAt, reachRate,
            jointReachPresent: pPresentAt.map((p, k) => p * reachRate[k]),
            perRival: state.players.filter(p => p.id !== viewer).map(p => ({ playerId: p.id, pClaimWithin: 0 })),
            samples: 0, notes,
        };
    }
    const records = (batch ?? runRaceRollouts(state, ctx.history, golemId, ctx, ctx.config.rollouts, deadline)).records;
    const samples = records.length || 1;
    const rivalClaim = new Map();
    for (const p of state.players)
        if (p.id !== viewer)
            rivalClaim.set(p.id, 0);
    for (const rec of records) {
        // 决策点 τ_k 的存活性与到达率（条件于观察席位到达该决策点的口径见 reachRate）。
        for (let k = 1; k <= H; k++) {
            const reached = rec.presence[viewer]?.length >= k;
            if (reached) {
                reachRate[k] += 1;
                if (rec.presence[viewer][k - 1])
                    pPresentAt[k] += 1;
            }
            // 未到达（对局提前结束）：决策点不存在，不计入条件样本。
        }
        const claim = rec.claims[0];
        if (claim && claim.playerId !== viewer) {
            rivalClaim.set(claim.playerId, (rivalClaim.get(claim.playerId) ?? 0) + 1);
        }
    }
    for (let k = 1; k <= H; k++) {
        pPresentAt[k] = reachRate[k] > 0 ? pPresentAt[k] / reachRate[k] : 0;
        reachRate[k] /= samples;
    }
    const jointReachPresent = pPresentAt.map((p, k) => p * reachRate[k]);
    const perRival = [...rivalClaim.entries()]
        .map(([pid, c]) => ({ playerId: pid, pClaimWithin: c / samples }))
        .sort((a, b) => b.pClaimWithin - a.pClaimWithin);
    return { golemId, viewerId: viewer, horizon: H, pPresentAt, reachRate, jointReachPresent, perRival, samples: records.length, notes };
}
/** 批量便捷入口：全部公开魔像的存活预测（Joint Search 消费形态）。 */
export function predictAllSurvivals(ctx, horizon, deadline) {
    const { state, config } = ctx;
    const H = horizon ?? config.horizon;
    const out = [];
    for (const golemId of state.golemMarket) {
