    if (seenStocks) {
        const key = running.join(',');
        if (seenStocks.has(key))
            return;
        seenStocks.add(key);
    }
    out.push({ type: 'play', cardId, steps: [...prefix] });
    if (depth >= maxSteps)
        return;
    for (let color = 0; color < 3; color++) {
        if (running[color] <= 0)
            continue;
        running[color]--;
        running[color + 1]++;
        prefix.push(color);
        collectUpgradeSteps(running, maxSteps, depth + 1, prefix, cardId, out, seenStocks);
        prefix.pop();
