    for (let color = firstColor; color < 4; color++) {
        if (available[color] <= 0)
            continue;
        available[color]--;
        prefix.push(color);
        collectDiscards(available, excess, depth + 1, prefix, out);
        prefix.pop();
        available[color]++;
